/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('petrol','Petrol entered English in 1895 from French pétrol for refined petroleum used in motor cars; an earlier English use referred to the unrefined substance.',[C('petrol.s1','交通','The rental car stopped because its petrol tank was nearly empty, so Lena pulled into a filling station.','租来的汽车快没油而停了下来，莉娜便把车开进加油站。','The rental car stopped / because its petrol tank was nearly empty / so Lena pulled into a filling station.','petrol.s1 指汽车发动机使用的液体燃料，即英式英语的汽油。','油箱见底后需要到加油站补充燃料。'),C('petrol.s2','商业','The station raised the price of petrol overnight, and the receipt showed the new cost per litre.','加油站一夜之间提高了汽油售价，收据上标出了新的每升价格。','The station raised / the price of petrol / overnight / and the receipt showed the new cost per litre.','petrol.s2 指加油站出售给司机购买的汽油商品。','每升价格和收据突出其商品义。')],M('In Britain, the driver filled the car with petrol, meaning a drink of water for the engine.','In Britain, the driver filled the car with petrol, meaning gasoline for the engine.','petrol 指供发动机燃烧的燃油，不是发动机用水。','meaning'),[Q(1,'Why did Lena stop at the filling station?','The rental car was almost out of fuel.','Its oil tank was full of cooking oil.','She needed to buy a new engine.','Petrol is the liquid fuel used by many car engines.'),Q(2,'What price changed overnight?','The amount charged per litre for fuel sold at the station.','The cost of a yearly car registration.','The price of an empty fuel tank.','Here petrol means the fuel offered for sale to drivers.'),Q(1,'In British usage, petrol is closest in meaning to which US term?','Gasoline.','Kerosene lamp.','Engine coolant.','Petrol is the British word for gasoline.'),Q(2,'What does the receipt’s price per litre measure?','The cost of petrol being sold as a product.','The car’s total distance traveled.','The engine’s temperature.','The station sells petrol by volume, here measured per litre.','distinction')]);
P('petroleum','Petroleum is from Medieval Latin petroleum, combining Latin petra “rock” and oleum “oil,” literally “rock oil.”',[C('petroleum.s1','能源','Geologists drilled through layers of shale and sandstone before finding petroleum trapped in a deep reservoir.','地质学家钻穿页岩和砂岩层后，才发现深层储油层中蕴藏着石油。','Geologists drilled / through layers of shale and sandstone / before finding petroleum / trapped in a deep reservoir.','petroleum.s1 指地下天然蕴藏的石油原料，可进一步炼制。','深层储油层中发现的是未经炼制的石油资源。'),C('petroleum.s2','能源','The region’s economy still depends heavily on the petroleum industry, from drilling to refining and shipping.','该地区经济仍高度依赖石油产业，涵盖钻探、炼油和运输。','The region’s economy still depends / heavily on the petroleum industry / from drilling / to refining and shipping.','petroleum.s2 指作为资源和产业的石油。','钻探、炼制和运输是石油产业链。','word-formation')],M('The report said petroleum was a manufactured plastic that could not occur underground or be refined.','The report said petroleum was a naturally occurring oil that could be refined into fuels and chemicals.','petroleum 是地下天然存在的油类原料，而非只能人工制造的塑料。','meaning'),[Q(1,'What did the geologists discover in the reservoir?','Oil occurring naturally underground.','A finished plastic bottle.','A deposit of fresh drinking water.','Petroleum is oil found in the ground and refined into products.'),Q(2,'Which activities belong to the petroleum industry?','Drilling, refining, and transporting oil.','Growing wheat and baking bread.','Making paper from recycled books.','The industry covers extracting and processing petroleum.'),Q(1,'Why does the word petroleum literally suggest “rock oil”?','Its historical formation combines Latin words for rock and oil.','It was first used for oil painted on rocks.','It names a type of rock that burns without fuel.','Petra means rock and oleum means oil in the cited Latin formation.' ,'word-formation'),Q(2,'In the economic example, what does petroleum industry refer to?','The network of businesses that extract and process oil.','A single underground oil sample only.','A geology textbook about sandstone.','The phrase refers to the resource-based industrial sector.')]);
P('petticoat','Petticoat is an early-15th-century compound of petty + coat, literally “small coat”; it first named a short men’s coat and later a garment worn beneath a dress.',C('petticoat.s1','服饰','Before putting on her formal gown, Mei smoothed a lightweight petticoat beneath the skirt to give it shape.','穿上礼服前，梅把一条轻薄衬裙抚平在裙子下面，让外裙更有形。','Before putting on her formal gown / Mei smoothed a lightweight petticoat / beneath the skirt / to give it shape.','petticoat.s1 指穿在连衣裙或外裙下面的衬裙。','beneath the skirt 明确表明衬裙穿在外裙之下。','word-formation'),M('She wore the petticoat over her gown so that everyone could see it as the outer dress.','She wore the petticoat beneath her gown as an under-skirt.','petticoat 是穿在外裙里面的衬裙，不是外穿的礼服。','meaning'),[Q(1,'Where did Mei wear the petticoat?','Under the outer skirt.','Over the gown as a coat.','Around her shoulders as a shawl.','A petticoat is a skirt worn beneath a dress.'),Q(1,'What clothing item is a petticoat?','An under-skirt worn beneath a dress.','A short-sleeved shirt worn over a coat.','A belt used to hold up trousers.','Its modern sense is an underskirt.'),Q(1,'How did the petticoat help the formal gown?','It gave the skirt shape from underneath.','It replaced the gown as an outer jacket.','It fastened the shoes to the feet.','An underskirt can support or shape the outer skirt.'),Q(1,'What does the old compound literally mean?','A small coat.','A long outer cloak.','A child’s shoe.','Petticoat combines petty, “small,” and coat.')]);
P('petty','Petty came from Old French petit “small”; English first used it neutrally for something minor, then also for small-minded or spiteful behavior.',[C('petty.s1','通用','The committee postponed the vote to settle a petty disagreement about the color of the meeting-room folders.','委员会推迟了投票，只为解决一个关于会议室文件夹颜色的琐碎分歧。','The committee postponed the vote / to settle a petty disagreement / about the color / of the meeting-room folders.','petty.s1 指小到不值得过多关注的、琐碎的。','文件夹颜色相较投票显得不重要。'),C('petty.s2','人际','He made a petty comment about her typo long after the important issue had been resolved.','重要问题早已解决，他却仍为她的拼写错误说了句小气刻薄的话。','He made a petty comment / about her typo / long after the important issue / had been resolved.','petty.s2 指为小事斤斤计较、刻薄或心胸狭窄的。','揪住无关紧要的错处挖苦他人体现小气。'),C('petty.s3','法律','The court treated the first-time shoplifting charge as a petty offense because the value was very low.','由于涉案金额很低，法院把这起初犯盗窃案按轻微违法处理。','The court treated / the first-time shoplifting charge / as a petty offense / because the value was very low.','petty.s3 指轻微的罪行或金额小的事项。','低金额和轻微违法对应法律语境中的 petty。')],M('She was petty when she calmly let the harmless typo go and focused on the serious safety problem.','She was petty when she kept mocking the harmless typo instead of discussing the serious safety problem.','放过小错、专注重要问题不体现 petty 的小气刻薄。','meaning'),[Q(1,'Why was the disagreement called petty?','It concerned a minor detail rather than an important issue.','It involved a serious threat to public safety.','It determined the committee’s final vote.','Petty.s1 means too small to deserve much attention.'),Q(2,'What made his comment petty?','He kept making a spiteful remark about a trivial typo.','He offered a careful correction in private.','He concentrated on resolving the main issue.','Petty.s2 describes small-minded or spiteful behavior.'),Q(3,'Why did the court call the offense petty?','The offense and amount involved were minor.','The accused ran an international criminal group.','The case involved a large public danger.','Petty can describe a minor crime or small sum.'),Q(2,'Which response sounds petty?','Mocking a colleague over a harmless, tiny mistake.','Thanking a colleague for fixing an urgent error.','Ignoring a trivial issue to solve a major one.','Petty behavior is spiteful about small matters.','distinction')]);
P('phantom','Phantom came through Old French fantosme and Latin phantasma from Greek phantasma “apparition,” related to the idea of something appearing.',C('phantom.s1','通用','In the fog, the sailor mistook a torn sail on the shore for a phantom standing beside the lighthouse.','雾中，水手把岸边的一块破帆误看成站在灯塔旁的幽灵。','In the fog / the sailor mistook a torn sail on the shore / for a phantom / standing beside the lighthouse.','phantom.s1 指看似真实出现、实则并不存在的幻影或幽灵。','薄雾中把破帆看成幽灵，是误认幻影的情形。'),M('The sailor called the real lighthouse keeper a phantom because he was standing there in full daylight and speaking to the crew.','The sailor called the figure a phantom because it appeared in the fog but was only a torn sail.','确实在场并与水手交谈的守塔人不是幻影。','meaning'),[Q(1,'What did the sailor mistake for a phantom?','A torn sail seen through the fog.','The lighthouse’s working lamp.','A crew member carrying a rope.','A phantom seems present but is not actually there.'),Q(1,'Which sight would best fit the word phantom?','A figure that appears in mist but vanishes on inspection.','A person clearly standing nearby in bright light.','A statue whose location is known.','A phantom is an apparent but unreal presence.'),Q(1,'What does phantom mean in the example?','An apparent ghost or figure that is not really there.','A sailor who works at a lighthouse.','A type of ship’s sail.','The fog made the torn sail look like a ghostly figure.'),Q(1,'Why did the sailor misidentify the sail?','Fog made an object appear to be a ghostly figure.','The sail spoke and gave its name.','The lighthouse keeper had changed the ship’s route.','A phantom is an appearance mistaken for a real presence.','meaning')]);
P('pharaoh','Pharaoh passed through Latin Pharaonem, Greek Pharaō, and Hebrew Par\'oh from Egyptian pr-ꜥꜣ, literally “great house.”',C('pharaoh.s1','历史','The museum label explains that the pharaoh was treated as Egypt’s ruler and a divine king in ancient inscriptions.','博物馆说明牌指出，在古代铭文中，法老被视为埃及统治者和神性君王。','The museum label explains / that the pharaoh was treated / as Egypt’s ruler and a divine king / in ancient inscriptions.','pharaoh.s1 指古埃及国王，常被视为具有神性。','古代铭文中的王权和神性正是法老的历史身份。','word-formation'),M('The inscription called the elected mayor of modern Cairo a pharaoh of ancient Egypt, although he lived thousands of years later.','The inscription called the ancient Egyptian king a pharaoh.','现代市长不是古埃及王朝的君主，不能按历史身份称作法老。','meaning'),[Q(1,'Who was described as a pharaoh in the museum label?','An ancient Egyptian king.','A modern elected city mayor.','A Greek theater actor.','A pharaoh was a king of ancient Egypt.'),Q(1,'What did the title pharaoh historically name?','The ruler of ancient Egypt.','A priest who sold medicine.','A modern university degree.','The word names an ancient Egyptian royal title.'),Q(1,'What does the Egyptian source phrase pr-ꜥꜣ literally mean?','Great house.','River crossing.','Sun disk.','The title traces to Egyptian “great house.”','word-formation'),Q(1,'Why does the inscription connect the pharaoh with divinity?','Ancient rulers were regarded as divine kings.','The word means a temple musician.','Every Egyptian citizen held the royal title.','The source sense describes a king regarded as divine.')]);
P('pharmaceutical','Pharmaceutical is formed from pharmacy/pharmaceutic terminology ultimately related to Greek pharmakon “drug, medicine”; as a noun it names a medicine produced by the pharmaceutical industry.',[C('pharmaceutical.s1','医学','The laboratory follows pharmaceutical standards when testing the purity and stability of a new treatment.','实验室在检测新疗法的纯度和稳定性时遵循制药标准。','The laboratory follows / pharmaceutical standards / when testing the purity and stability / of a new treatment.','pharmaceutical.s1 作形容词，指与药物设计、生产或销售有关的。','它修饰 standards，说明这些规范属于制药领域。'),C('pharmaceutical.s2','医学','The hospital kept the pharmaceutical in a sealed cabinet until the pharmacist checked the prescription.','药剂师核对处方前，医院把这件药品保存在密封柜中。','The hospital kept / the pharmaceutical / in a sealed cabinet / until the pharmacist checked the prescription.','pharmaceutical.s2 作名词，指制药行业生产的一种药物。','处方核对和密封储存表明它是药品。')],M('The pharmaceutical company tested a pharmaceutical, meaning a wooden musical instrument rather than a medicine.','The pharmaceutical company tested a pharmaceutical, meaning a medicine produced by the drug industry.','名词 pharmaceutical 指药物，不是乐器。','meaning'),[Q(1,'What does pharmaceutical describe in “pharmaceutical standards”?','Standards connected with medicines and their production.','Rules for tuning a violin.','A hospital’s meal schedule.','As an adjective it relates to designing, making, or selling medicines.'),Q(2,'What was stored in the sealed cabinet?','A medicine produced by the pharmaceutical industry.','A bottle of cleaning solvent.','A printed instruction manual.','The noun pharmaceutical can mean a medicine.'),Q(1,'Which phrase uses pharmaceutical as an adjective?','A pharmaceutical laboratory.','A pharmaceutical was dispensed.','The pharmaceutical was sealed.','In the first phrase it modifies a noun and means drug-related.'),Q(2,'What should a pharmacist check before giving the pharmaceutical?','That the medicine matches the prescription.','That the orchestra has tuned its strings.','That the cabinet contains no labels.','The noun denotes the medicine being dispensed.','distinction')]);
P('pharmacology','Pharmacology combines pharmac- (from Greek pharmakon “drug”) with -logy “study”; it is the science of how drugs act in the body.',C('pharmacology.s1','医学','In pharmacology, the class compared how two doses of the same drug affected blood pressure in volunteers.','在药理学课程中，学生比较了同一种药的两种剂量对志愿者血压的影响。','In pharmacology / the class compared / how two doses of the same drug / affected blood pressure in volunteers.','pharmacology.s1 指研究药物如何作用于身体的科学。','比较药物剂量及其生理作用体现药理研究。','word-formation'),M('The chapter on pharmacology described only how pharmacists arrange medicine boxes on store shelves, not how drugs act in the body.','The chapter on pharmacology described how drugs act in the body.','药物如何影响身体才是 pharmacology 的核心，并非药盒陈列。','meaning'),[Q(1,'What did the pharmacology class compare?','The effects of two drug doses on blood pressure.','The colors of two pharmacy signs.','The prices of two hospital buildings.','Pharmacology studies how drugs act on the body.'),Q(1,'Which question belongs to pharmacology?','How does this medicine change heart rate?','How should a shop arrange its cash register?','Which color is best for a laboratory wall?','Drug effects in the body are pharmacological questions.'),Q(1,'What does the ending -logy contribute to pharmacology?','The idea of a field of study.','The idea of a retail counter.','The idea of a body part.','-logy forms names of fields of study.' ,'word-formation'),Q(1,'Why is pharmacology relevant to choosing a dose?','It examines the effects drugs have on the body.','It measures the dimensions of pill bottles.','It studies ancient royal titles.','Dose and bodily response are central to the science.')]);
P('pharmacy','Pharmacy came through French pharmacie from Greek pharmakeia, “use of drugs”; the English noun can name a medicine shop or the science and work of preparing medicines.',[C('pharmacy.s1','商业','After the clinic visit, Omar collected the prescription at a pharmacy across the street from the bus stop.','看完诊后，奥马尔在公交站对面的药店取了处方药。','After the clinic visit / Omar collected the prescription / at a pharmacy / across the street from the bus stop.','pharmacy.s1 指配制或出售药品的商店，也可指医院药房。','顾客在此取处方药，体现药店义。'),C('pharmacy.s2','教育','She studied pharmacy for four years and learned how to prepare, check, and dispense medicines safely.','她学习了四年药剂学，掌握了如何安全配制、核验和发放药物。','She studied pharmacy / for four years / and learned how to prepare, check, and dispense medicines / safely.','pharmacy.s2 指配药的学问和职业活动。','课程内容是安全配制与发药。','word-formation')],M('He studied pharmacy by learning how to design bridges and calculate their load limits.','He studied pharmacy by learning how to prepare and dispense medicines safely.','pharmacy 的学科义是配药学，不是桥梁工程。','meaning'),[Q(1,'Where did Omar collect his prescription?','At a medicine shop across from the bus stop.','At a bridge-design office.','At a concert hall.','A pharmacy can be a shop that prepares or sells medicine.'),Q(2,'What did she learn while studying pharmacy?','How to prepare, check, and dispense medicines.','How to construct a theater stage.','How to translate Egyptian inscriptions.','Pharmacy as a field concerns preparing and dispensing medicines.'),Q(1,'Which sentence uses pharmacy to mean a place?','I went to the pharmacy to pick up my prescription.','Pharmacy requires careful study of dosage.','She trained in pharmacy at university.','The first sentence names a retail place.'),Q(2,'Which activity best fits pharmacy as a profession?','Checking a prescription before dispensing a medicine.','Measuring the orbit of a planet.','Classifying a painting by style.','The professional work of preparing and dispensing medicines is pharmacy.')]);
P('pharynx','Pharynx is the anatomical term for the throat passage, borrowed from Greek pharynx “throat.”',C('pharynx.s1','医学','The physician examined the patient’s pharynx after she reported a sore throat and difficulty swallowing.','患者报告喉咙痛、吞咽困难后，医生检查了她的咽部。','The physician examined / the patient’s pharynx / after she reported a sore throat / and difficulty swallowing.','pharynx.s1 指喉咙中位于气管上方的咽部。','咽部检查与吞咽困难、喉咙痛相关。'),M('The doctor examined the pharynx in the patient’s ankle to investigate a throat infection.','The doctor examined the pharynx in the patient’s throat to investigate an infection.','pharynx 是咽部，位于喉咙，不在脚踝。','meaning'),[Q(1,'What did the physician examine?','The patient’s throat passage.','The bones in her ankle.','The outer surface of her hand.','The pharynx is a part of the throat.'),Q(1,'Which symptom could prompt a pharynx examination?','Pain when swallowing.','A sprained wrist.','A blurred photograph.','The pharynx lies in the throat and is involved in swallowing.'),Q(1,'Where is the pharynx located?','In the throat above the windpipe.','Inside the ankle joint.','Behind the knee.','The pharynx is a throat structure above the trachea.'),Q(1,'Which specialist action matches the example?','Inspecting the throat after a patient reports swallowing difficulty.','Testing a car’s petrol tank.','Measuring an ancient coat.','The example links the pharynx to throat symptoms.')]);
P('phase','Phase came through French from Greek phasis “appearance,” from phainein “to show”; English uses it for stages, the moon’s appearance, and the verb meaning introduce or remove step by step.',[C('phase.s1','通用','The project entered a testing phase after the design team finished the first working model.','设计团队完成首个可运行模型后，项目进入测试阶段。','The project entered / a testing phase / after the design team / finished the first working model.','phase.s1 指变化或发展过程中的一个阶段。','after 标记项目由设计转入测试的阶段变化。'),C('phase.s2','管理','The city will phase out diesel buses over five years rather than replacing the entire fleet at once.','该市将用五年逐步淘汰柴油公交车，而不是一次性更换整支车队。','The city will phase out diesel buses / over five years / rather than replacing / the entire fleet at once.','phase.s2 作动词，指分阶段逐步引入或取消。','over five years 强调逐步完成。'),C('phase.s3','天文','A thin crescent is the moon’s current phase, visible just after sunset.','一弯新月是月亮当前的月相，日落后不久可以看到。','A thin crescent / is the moon’s current phase / visible just after sunset.','phase.s3 指月亮呈现的特定形状或局面的一个方面。','crescent 是月亮的一种可见形态。')],M('The city phased out the old buses in one instant by keeping every one of them in service for five years.','The city phased out the old buses gradually over five years.','phase out 表示逐步淘汰；全部继续使用且未淘汰与之矛盾。','meaning'),[Q(1,'When did the project enter its testing phase?','After the first working model was finished.','Before anyone began the design.','After the buses were all removed.','A phase is a stage in a process.'),Q(2,'How will the city phase out diesel buses?','Gradually over five years.','All at once tonight.','By extending their service forever.','To phase out means remove something step by step.'),Q(3,'What does the thin crescent show?','The moon’s current visible phase.','A bus replacement schedule.','A project’s testing calendar.','A phase can be a particular appearance of the moon.'),Q(2,'Which sentence uses phase as a verb?','They will phase in the new rules over several months.','The moon is in a bright phase.','Testing is the final phase of the project.','“Phase in” is a verb meaning introduce in stages.','distinction')]);
P('phd','PhD abbreviates Latin Philosophiae Doctor, “Doctor of Philosophy,” the highest university degree in many systems.',C('phd.s1','教育','After completing her dissertation and oral defense, Nia earned a PhD in materials science.','完成论文和口试答辩后，妮娅获得了材料科学博士学位。','After completing her dissertation and oral defense / Nia earned / a PhD / in materials science.','phd.s1 指博士学位，常写作 PhD，原称 Doctor of Philosophy。','论文和答辩是博士学位的典型要求。','word-formation'),M('Nia earned a PhD in materials science after completing only a one-week introductory workshop.','Nia earned a PhD in materials science after completing doctoral research and defending her dissertation.','PhD 是高级博士学位，不能仅凭一周入门培训获得。','meaning'),[Q(1,'What did Nia earn after her dissertation defense?','A doctoral degree in materials science.','A one-week workshop certificate.','A medical prescription.','A PhD is a university doctoral degree.'),Q(1,'What does PhD abbreviate?','Doctor of Philosophy.','Public Health Department.','Photographic Development.','PhD represents the Latin title Philosophiae Doctor.' ,'word-formation'),Q(1,'Which achievement normally fits the example?','Completing doctoral research and defending a dissertation.','Attending one introductory class.','Buying a textbook at a pharmacy.','The example describes the work associated with a doctorate.'),Q(1,'How should the degree abbreviation usually be written?','PhD.','phd.','PHDs as the singular title.','The standard abbreviation capitalizes P and D and uses a lowercase h.')]);
P('phenomenal','Phenomenal is built from phenomenon + -al; its common evaluative sense is “extraordinary,” while another sense means relating to observable phenomena.',[C('phenomenal.s1','评价','The small bakery had a phenomenal first year, selling out of bread before noon almost every day.','这家小面包店第一年成绩惊人，几乎每天中午前面包就售罄。','The small bakery had / a phenomenal first year / selling out of bread / before noon almost every day.','phenomenal.s1 指非凡的、远超平常的。','反复提前售罄说明成绩异常出色。'),C('phenomenal.s2','科学','The researcher separated phenomenal observations, such as color and brightness, from claims about hidden causes.','研究者把颜色、亮度等现象层面的观察与关于隐蔽原因的主张区分开来。','The researcher separated / phenomenal observations / such as color and brightness / from claims about hidden causes.','phenomenal.s2 指与可观察到的现象有关的。','颜色和亮度是直接观察到的表现。')],M('The bakery’s phenomenal year was described as completely ordinary, with no unusual success or results.','The bakery’s phenomenal year was extraordinary, with sales far above its expectations.','phenomenal 的常用评价义是非凡的，不是完全普通。','meaning'),[Q(1,'Why was the bakery’s first year called phenomenal?','It sold out unusually early on most days.','It closed before selling any bread.','Its sales exactly matched a poor forecast.','Phenomenal in the common sense means exceptionally impressive.'),Q(2,'Which items did the researcher call phenomenal observations?','Visible features such as color and brightness.','An unobserved cause assumed without evidence.','A bakery’s yearly income statement.','The technical sense concerns observable phenomena.'),Q(1,'Which result is phenomenal in ordinary praise?','A team breaks a record by a huge margin.','A team performs exactly at an ordinary level.','A team cancels every event.','The everyday adjective praises an extraordinary result.'),Q(2,'In a scientific discussion, “phenomenal properties” most directly concern what?','Features as they are observed or experienced.','The hidden cause already proved by experiment.','The price of a medicine.','The less common sense ties phenomenal to observable phenomena.','distinction')]);
P('phenomenally','Phenomenally is formed from phenomenal + -ly; it commonly means “to an extraordinary degree,” and can also mean “in terms of observable phenomena.”',[C('phenomenally.s1','评价','The rescue team worked phenomenally quickly, reaching the stranded hikers before nightfall.','救援队行动快得惊人，在夜幕降临前赶到了被困的徒步者那里。','The rescue team worked / phenomenally quickly / reaching the stranded hikers / before nightfall.','phenomenally.s1 指程度非凡地、极其。','副词修饰 quickly，强调速度远超平常。'),C('phenomenally.s2','哲学','The report described the object phenomenally—as it appeared to observers—without claiming what it was made of.','报告从现象角度描述该物体，即记录观察者所见，而不声称知道它由什么构成。','The report described the object phenomenally / as it appeared to observers / without claiming / what it was made of.','phenomenally.s2 指就可观察到的现象而言。','描述外观但不推断本质，体现现象层面的用法。')],M('The team arrived phenomenally late, meaning they arrived far earlier than the scheduled time.','The team arrived phenomenally late, meaning they arrived remarkably far after the scheduled time.','late 表示晚到，phenomenally 强调程度很高，不能释为远早于。','meaning'),[Q(1,'How quickly did the rescue team work?','At an extraordinarily fast rate.','At a rate slower than anyone else.','At exactly the usual pace.','Phenomenally can intensify an adjective or adverb to an exceptional degree.'),Q(2,'How did the report describe the object?','By recording how it appeared to observers.','By claiming a hidden composition without evidence.','By comparing its market price.','Phenomenally can mean in terms of observable appearances.'),Q(1,'Which sentence uses phenomenally as an intensifier?','The launch was phenomenally successful.','The launch’s observable color was noted.','The report avoided describing what viewers saw.','Phenomenally successful means successful to a remarkable degree.'),Q(2,'What does “phenomenally, the surface looked blue” emphasize?','The observed appearance of the surface.','The proved chemical cause of the color.','A high degree of speed.','Here phenomenally frames a description of observable appearance.','distinction')]);
P('phenomenon','Phenomenon comes through Latin from Greek phainomenon “that which appears,” from phainesthai “to appear”; it names an observable event or, informally, an unusually impressive person or thing.',[C('phenomenon.s1','科学','The aurora is a natural phenomenon caused by charged particles interacting with gases high in the atmosphere.','极光是一种自然现象，由带电粒子与高层大气中的气体相互作用而形成。','The aurora is / a natural phenomenon / caused by charged particles / interacting with gases high in the atmosphere.','phenomenon.s1 指可观察到的事实或事件，尤其是尚未完全理解的现象。','极光是可观察的自然事件。'),C('phenomenon.s2','口语','At sixteen, the chess phenomenon defeated several adult champions in the same weekend tournament.','这位十六岁的国际象棋奇才在同一场周末赛事中击败了几位成年冠军。','At sixteen / the chess phenomenon defeated / several adult champions / in the same weekend tournament.','phenomenon.s2 指极为出色或不寻常的人或事物。','年纪轻轻击败多位冠军，说明他非常非凡。')],M('Scientists called the aurora a phenomenon even though nobody could observe it or record any event.','Scientists called the visible aurora a phenomenon because it was an observable natural event.','phenomenon 在科学义中指可观察到的事实或事件，完全不可观察的事物不符合。','meaning'),[Q(1,'What kind of phenomenon is the aurora?','An observable natural event in the atmosphere.','A chess player winning a tournament.','A drug sold at a pharmacy.','The scientific sense of phenomenon is an observable event.'),Q(2,'Why was the teenager called a chess phenomenon?','He was unusually impressive and defeated adult champions.','He had never played a chess game.','He studied how drugs affect the body.','Informally, a phenomenon can be a remarkably talented person.'),Q(1,'What is the plural of phenomenon?','Phenomena.','Phenomenonses.','Phenomenal.','The Greek-derived noun has the plural phenomena.' ,'word-formation'),Q(2,'Which person could be called a phenomenon?','A young musician whose skill is far beyond expectation.','A beginner who has not yet learned an instrument.','A person who only sells concert tickets.','The informal sense describes an exceptionally impressive person.')]);
P('pheromone','Pheromone was coined in 1959 from Greek pherein “to carry” + hormone, for a chemical signal carried or released by an organism that affects others of the same species.',C('pheromone.s1','生物','A female moth released a pheromone that guided males of the same species toward her from far away.','一只雌蛾释放信息素，引导远处的同种雄蛾靠近。','A female moth released / a pheromone / that guided males of the same species / toward her from far away.','pheromone.s1 指生物分泌、影响同种其他个体行为的化学信号。','性信息素在同种个体间传递求偶信号。','word-formation'),M('The moth released a pheromone that signaled to every plant species in the forest to start flowering.','The moth released a pheromone that signaled to other moths of its species.','信息素是作用于同种动物的化学信号，并非向所有植物发送信号。','meaning'),[Q(1,'What guided the male moths toward the female?','A chemical signal released by the female.','A flashing electric light.','A sound made by a different species.','A pheromone is a chemical signal released by an organism.'),Q(1,'Who responded to the moth’s pheromone in the example?','Males of the same species.','Every plant in the forest.','A human observer in the lab.','Pheromones affect other members of the same species.'),Q(1,'Which situation involves a pheromone?','An ant leaves a chemical trail that other ants follow.','A radio broadcasts a weather report.','A flower reflects sunlight without releasing chemicals.','The ant’s chemical signal communicates with others of its species.'),Q(1,'What does the source element pherein mean?','To carry.','To see.','To divide.','The coined word combines Greek pherein “carry” with hormone.','word-formation')]);
P('Philadelphia','The Pennsylvania city’s name was taken by William Penn from Greek and meant “brotherly love,” from philos “loving” + adelphos “brother.”',C('Philadelphia.s1','地理','The delegates met in Philadelphia, where the Declaration of Independence was signed in 1776.','代表们在费城会面；《独立宣言》于1776年在此签署。','The delegates met / in Philadelphia / where the Declaration of Independence / was signed in 1776.','Philadelphia.s1 指特拉华河畔的美国宾夕法尼亚州城市费城。','独立宣言签署地点是费城的重要历史背景。','word-formation'),M('The delegates signed the Declaration of Independence in Philadelphia, a city located in the Pacific Ocean.','The delegates signed the Declaration of Independence in Philadelphia, a city in Pennsylvania.','费城位于宾夕法尼亚州，不在太平洋中。','meaning'),[Q(1,'Where did the delegates meet in the example?','In the Pennsylvania city of Philadelphia.','In a city on the Pacific Ocean.','In an ancient Egyptian temple.','Philadelphia is a major city in Pennsylvania.'),Q(1,'What major event is associated with Philadelphia in the sentence?','The signing of the Declaration of Independence in 1776.','The invention of the telephone.','The discovery of petroleum.','The example identifies the city as the signing location.'),Q(1,'What does the name Philadelphia mean in its Greek formation?','Brotherly love.','Love of music.','Study of ancient texts.','The name combines Greek philos “loving” and adelphos “brother.”','word-formation'),Q(1,'Which river is associated with the city’s location?','The Delaware River.','The Nile.','The Amazon.','Philadelphia stands between the Delaware and Schuylkill rivers.')]);
P('philanthropist','Philanthropist is formed from philanthropy + -ist; philanthropy comes from Greek philanthrōpia, “love of humankind,” and -ist names a person who does something.',C('philanthropist.s1','社会','The philanthropist funded a mobile clinic so families in remote villages could receive basic medical care.','这位慈善家资助了一家流动诊所，让偏远村庄的家庭也能获得基础医疗。','The philanthropist funded / a mobile clinic / so families in remote villages / could receive basic medical care.','philanthropist.s1 指通过捐赠或行动促进他人福祉的人。','资助诊所是以实际行动帮助他人。','word-formation'),M('The newspaper called the donor a philanthropist because he kept his entire fortune and refused every effort to help others.','The newspaper called the donor a philanthropist because he used his wealth to support services for others.','拒绝帮助他人与以行动促进公众福祉的慈善家含义相反。','meaning'),[Q(1,'What did the philanthropist fund?','A mobile clinic for remote villages.','A private racing car for himself.','A factory that polluted the local water.','A philanthropist uses resources to benefit other people.'),Q(1,'Which person best fits philanthropist?','A donor who supports public health and education.','A shopkeeper who sells medicine for profit only.','A scientist who studies the moon’s phases.','A philanthropist actively works for human welfare.'),Q(1,'What role does the suffix -ist play in philanthropist?','It names a person associated with an activity or practice.','It means a place where medicine is sold.','It marks an adjective meaning “small.”','-ist is an agent-forming element for a person who does something.','word-formation'),Q(1,'Why is the clinic example an act of philanthropy?','It provides practical help to families who lack nearby care.','It earns no income for the philanthropist’s private company.','It teaches only the history of Greek words.','The act benefits others through practical support.')]);
P('philharmonic','Philharmonic came through French and Italian from Greek philos “loving” + ta harmonika “harmony, music”; the adjective refers to music or an orchestra.',C('philharmonic.s1','音乐','The philharmonic orchestra rehearsed Mahler’s symphony before performing it for a packed concert hall.','爱乐交响乐团在满座的音乐厅演出前排练了马勒的交响曲。','The philharmonic orchestra rehearsed / Mahler’s symphony / before performing it / for a packed concert hall.','philharmonic.s1 指爱乐的，或与演奏古典音乐的乐团有关的。','它修饰 orchestra，指古典音乐演奏团体。','word-formation'),M('The philharmonic orchestra rehearsed the symphony by replacing every instrument with silent paper models.','The philharmonic orchestra rehearsed the symphony with its musicians and instruments.','爱乐乐团排练音乐需要实际演奏者和乐器，不是静止的纸模型。','meaning'),[Q(1,'What did the philharmonic orchestra rehearse?','A symphony by Mahler.','A speech about petroleum prices.','A medical prescription.','Philharmonic in the example describes an orchestra that performs music.'),Q(1,'Which institution is most likely philharmonic?','An orchestra that gives classical music concerts.','A pharmacy that fills prescriptions.','A laboratory that studies drug effects.','Philharmonic is associated with music and orchestras.'),Q(1,'What does the Greek element philo- contribute?','Loving or fond of.','Brother.','Throat.','Philharmonic combines a “loving” element with harmony or music.' ,'word-formation'),Q(1,'Why were musicians rehearsing before the concert?','To prepare the symphony for performance.','To inspect a throat passage.','To change a bus fleet in stages.','The adjective concerns music and the orchestra’s performance.')]);
P('philological','Philological is formed from philology + -ical; philology came from Greek philologia, the love or study of words, language, and texts.',C('philological.s1','语言','The philological notes compare spellings in medieval manuscripts to trace how the word changed over centuries.','语文学注释比较了中世纪手稿中的拼写，以追踪这个词几个世纪以来的变化。','The philological notes compare spellings / in medieval manuscripts / to trace how the word / changed over centuries.','philological.s1 指与语言及古代文本研究有关的。','比较历史手稿拼写是语文学研究方法。','word-formation'),M('Her philological study traced a word’s spelling through manuscripts but focused on measuring the chemical purity of petrol.','Her philological study traced a word’s spelling through manuscripts and compared its historical forms.','研究历史词形和手稿属于语文学；检测汽油纯度则属于化学。','distinction'),[Q(1,'What did the philological notes compare?','Spellings in medieval manuscripts.','The chemical composition of petrol.','The phases of the moon.','Philological work studies language and old texts.'),Q(1,'Which project is philological?','Tracing how a word changed across historical documents.','Testing how a medicine affects blood pressure.','Measuring an animal’s pheromone response.','The first project studies the history of words in texts.'),Q(1,'What does philological most directly modify in “philological notes”?','Notes about language and texts.','Notes about oil drilling.','Notes about orchestral volume.','The adjective means relating to philology.'),Q(1,'Why are medieval manuscripts useful in the example?','They preserve older spellings that reveal language change.','They show the current price of petrol.','They record the moon’s present phase.','Historical texts provide evidence for philological study.','meaning')]);
P('philology','Philology comes from Greek philologia, “love of learning or words,” and English uses it for the historical study of languages and literary texts.',C('philology.s1','语言','The philology seminar compared Latin inscriptions with later manuscripts to trace how the verb changed over time.','语文学研讨课比较了拉丁铭文与后来的手稿，以追踪这个动词如何随时间变化。','The philology seminar compared / Latin inscriptions with later manuscripts / to trace how the verb / changed over time.','philology.s1 指通过书面文献研究语言及其历史。','跨时代比较铭文和手稿是历史语文学的方法。','word-formation'),M('The researcher called the project philology although it studied only how modern medicines affect blood pressure.','The researcher called the project philology because it traced language history through old texts.','只研究药物对血压的影响属于医学研究，不是语文学。','distinction'),[Q(1,'What did the philology seminar compare?','Inscriptions and later manuscripts.','Two medicine doses.','Two orchestral performances.','Philology studies languages and texts historically.'),Q(1,'Which project is philology?','Tracing a word’s forms through centuries of documents.','Testing a new drug in a clinical trial.','Measuring a chemical’s brightness.','The first project uses written evidence to study language history.'),Q(1,'Why are old texts important to philology?','They show how language and literature changed.','They reveal the current exchange rate.','They measure the throat’s anatomy.','Historical documents are evidence for philological research.'),Q(1,'What does the Greek element philo- contribute to philology?','Love or interest.','A written copy.','A unit of sound.','Philologia was associated with love of learning or words.','word-formation')]);
P('philosopher','Philosopher comes from Greek philosophos, literally “lover of wisdom”; it can name a scholar of philosophy or, more broadly, a calm and reasonable person.',[C('philosopher.s1','教育','The philosopher argued that a fair law must apply equally, then defended the claim with careful reasoning.','这位哲学家论证公平的法律应当平等适用，并用严谨推理为观点辩护。','The philosopher argued / that a fair law must apply equally / then defended the claim / with careful reasoning.','philosopher.s1 指研究哲学的学者或思想家。','通过论证公平原则体现哲学讨论。'),C('philosopher.s2','性格','Even after losing his home in the flood, the old farmer remained a philosopher and spoke calmly about starting again.','洪水冲毁家园后，这位老农仍很达观，平静地谈论重新开始。','Even after losing his home in the flood / the old farmer remained a philosopher / and spoke calmly / about starting again.','philosopher.s2 可指遭遇不幸仍冷静讲理、达观的人。','逆境中的沉着对应引申义。')],M('The philosopher panicked at every small setback and refused to think calmly about any problem.','The philosopher stayed calm and reasonable while considering the setback.','此处哲学家引申为处事冷静的人；慌乱不能体现这种用法。','meaning'),[Q(1,'What did the philosopher defend with careful reasoning?','The claim that fair laws should apply equally.','The idea that laws should be hidden.','A plan to measure the moon’s phases.','A philosopher studies and argues about questions of thought and values.'),Q(2,'Why was the farmer called a philosopher after the flood?','He stayed calm and reasonable despite misfortune.','He taught a university course in ancient Greek.','He refused to speak to anyone.','The broader sense describes a composed person in adversity.'),Q(1,'Which person is a philosopher in the academic sense?','A scholar who studies questions about knowledge and justice.','A driver who buys petrol at a station.','A musician tuning a philharmonic orchestra.','The academic sense is a scholar of philosophy.'),Q(2,'Which reaction best fits the figurative sense of philosopher?','Thinking steadily after a serious disappointment.','Shouting over every trivial inconvenience.','Pretending a real danger does not exist.','The figurative sense implies calm reason under difficulty.','distinction')]);
P('philosophic','Philosophic derives from philosophy and Greek philosophikos, “of a lover of wisdom”; it can mean relating to philosophy or calmly accepting a setback.',[C('philosophic.s1','思想','The essay takes a philosophic approach to freedom, asking what responsibility means rather than listing political slogans.','这篇文章以哲学方式探讨自由，追问责任的含义，而非罗列政治口号。','The essay takes / a philosophic approach to freedom / asking what responsibility means / rather than listing political slogans.','philosophic.s1 指哲学的，或体现哲学思考方式的。','探究自由与责任的含义，体现哲学思考。'),C('philosophic.s1','性格','When the train was canceled, Noor took a philosophic view and calmly chose another route.','火车取消后，努尔以达观的态度平静地选择了另一条路线。','When the train was canceled / Noor took a philosophic view / and calmly chose / another route.','philosophic.s1 也可形容对挫折理性冷静的态度。','遇到变化后平静应对体现达观义。')],M('She took a philosophic view of the canceled train by screaming at staff and refusing every practical solution.','She took a philosophic view of the canceled train by calmly considering another route.','达观冷静的态度与对工作人员尖叫并拒绝解决办法相反。','meaning'),[Q(1,'What makes the essay’s approach philosophic?','It examines the meaning of freedom and responsibility.','It lists train departure times only.','It describes how to mix medicines.','Philosophic can mean concerned with philosophy or its methods.'),Q(1,'How did Noor respond philosophically to the cancellation?','She calmly chose another route.','She shouted and rejected every option.','She pretended the train had not been canceled.','The adjective can describe calm, rational acceptance of a setback.'),Q(1,'Which question sounds philosophic?','What makes a law just?','How many litres fit in a fuel tank?','Where is the nearest pharmacy?','The first asks a fundamental question about justice.'),Q(1,'What does “a philosophic view” suggest in the travel example?','A composed and reasonable attitude.','A technical study of train engines.','A belief that no routes exist.','The phrase uses the adjective for calm acceptance.')]);
P('philosophical','Philosophical is philosophy + -ical; it concerns philosophy or describes someone who remains calm and reasonable when something unpleasant happens.',[C('philosophical.s1','思想','The class held a philosophical debate about whether scientific progress always improves human well-being.','全班围绕科学进步是否总能改善人类福祉展开哲学辩论。','The class held / a philosophical debate / about whether scientific progress / always improves human well-being.','philosophical.s1 指与哲学或其思考方法有关的。','问题涉及进步与福祉的根本价值判断。'),C('philosophical.s2','性格','After the team lost the final, the captain was philosophical and congratulated the winners without bitterness.','球队输掉决赛后，队长很达观，没有怨气地向冠军队表示祝贺。','After the team lost the final / the captain was philosophical / and congratulated the winners / without bitterness.','philosophical.s2 指遇到不快时冷静、想得开。','失利后坦然祝贺对手体现达观。')],M('After losing the final, the captain was philosophical, throwing equipment and refusing to accept that the match was over.','After losing the final, the captain was philosophical, calmly accepting the result and congratulating the winners.','冷静接受结果才是 philosophical 的达观义，发怒砸东西与之相反。','meaning'),[Q(1,'What did the class debate?','Whether scientific progress always benefits people.','How much petrol a car uses.','Which petticoat to wear.','A philosophical debate examines fundamental questions and ideas.'),Q(2,'How did the captain act after the loss?','He accepted the result calmly and congratulated the winners.','He smashed equipment in anger.','He claimed that no match had occurred.','The second sense means composed and reasonable after disappointment.'),Q(1,'Which topic is philosophical?','What counts as a good life?','Where can I buy a ticket?','How many pages are in this manual?','The first question concerns fundamental values and meaning.'),Q(2,'Which reaction is philosophical in the figurative sense?','Taking a disappointing result calmly.','Insisting that every small setback is a disaster.','Refusing to listen to a reasonable explanation.','This sense describes calmness when something unpleasant happens.','distinction')]);
P('philosophy','Philosophy comes through Latin from Greek philosophia “love of wisdom,” from philos “loving” + sophia “wisdom”; it also means a guiding set of personal beliefs.',[C('philosophy.s1','教育','The course in philosophy asked students to compare arguments about knowledge, reality, and what makes an action right.','哲学课程要求学生比较有关知识、实在以及何为正当行为的论证。','The course in philosophy asked students / to compare arguments / about knowledge, reality / and what makes an action right.','philosophy.s1 指研究知识、实在和人生规范等问题的学科。','课程围绕知识、实在与道德问题展开。'),C('philosophy.s2','生活','Her philosophy of management is to give people clear goals, then trust them to decide how to meet those goals.','她的管理处世原则是先给员工明确目标，再相信他们自行决定如何实现。','Her philosophy of management / is to give people clear goals / then trust them / to decide how to meet those goals.','philosophy.s2 指指导个人生活或工作的信念与原则。','句子表达一套指导管理实践的信念。')],M('His philosophy of leadership was a random collection of unrelated choices that never guided how he worked.','His philosophy of leadership was a set of beliefs that guided how he worked.','处世 philosophy 是能指导行动的一套信念，不是毫无关联、从不指导行为的选择。','meaning'),[Q(1,'What questions did the philosophy course examine?','Questions about knowledge, reality, and right action.','Questions about fuel prices only.','Questions about the color of a skirt.','Philosophy studies fundamental questions about knowledge and how people should live.'),Q(2,'What is the manager’s philosophy?','Set clear goals and trust people to choose how to reach them.','Make every decision randomly.','Avoid giving anyone a goal.','A personal philosophy can be a guiding set of work principles.'),Q(1,'What does the Greek root sophia mean in philosophy?','Wisdom.','Brother.','Sound.','Philosophia is “love of wisdom.”','word-formation'),Q(2,'Which statement is a philosophy of work?','“I believe careful feedback helps a team improve.”','“The meeting begins at nine.”','“The office has three windows.”','The first is a belief that can guide how someone works.')]);
P('phlegmatic','Phlegmatic comes through Latin from Greek phlegmatikos, originally relating to phlegm; in the older four-humor theory, a phlegmatic temperament was cool and unemotional.',C('phlegmatic.s1','性格','The phlegmatic dispatcher calmly coordinated the rescue teams while alarms rang and callers shouted around her.','警报响起、来电者在周围大喊时，这位沉着的调度员仍冷静地协调救援队。','The phlegmatic dispatcher calmly coordinated / the rescue teams / while alarms rang / and callers shouted around her.','phlegmatic.s1 指情绪稳定、不慌张、少有外露情绪的。','周围喧闹而她仍冷静，体现沉稳性情。','word-formation'),M('The phlegmatic dispatcher lost control at every alarm and could not make a calm decision.','The phlegmatic dispatcher stayed composed and made calm decisions despite the alarms.','易受惊慌、无法冷静与 phlegmatic 所指的沉稳相反。','meaning'),[Q(1,'How did the dispatcher act during the emergency?','She stayed composed and coordinated the teams.','She panicked at every sound.','She abandoned all communication.','Phlegmatic describes a calm, unemotional temperament.'),Q(1,'Which person seems phlegmatic?','A nurse who remains steady during a busy shift.','A guest who bursts into tears at every minor delay.','A caller who shouts without listening.','The nurse keeps composure under pressure.'),Q(1,'What historical idea is connected with phlegmatic?','An older theory of bodily humors and temperament.','The Greek name for a telephone.','A study of sound units in a language.','The adjective historically referred to phlegm in the four-humor theory.' ,'word-formation'),Q(1,'Which reaction would contradict being phlegmatic?','Staying calm while others are alarmed.','Keeping a steady voice during a crisis.','Becoming wildly agitated over every small event.','Phlegmatic implies composure rather than agitation.','distinction')]);
P('phobia','Phobia comes from Greek phobos “fear”; in modern use it names an intense, disproportionate fear of a particular thing.',C('phobia.s1','心理','Her phobia of elevators was so strong that she took the stairs even when the lift was empty and working safely.','她对电梯的恐惧症非常严重，即使电梯空着且安全运行，她也会走楼梯。','Her phobia of elevators was so strong / that she took the stairs / even when the lift / was empty and working safely.','phobia.s1 指强烈到超出普通谨慎程度的恐惧。','没有现实危险仍因强烈恐惧避开电梯。','word-formation'),M('His phobia of dogs was ordinary caution after seeing one behind a locked fence, with no fear or avoidance.','His phobia of dogs was an intense fear that made him avoid even calm dogs at a safe distance.','普通谨慎不是 phobia；该词指强烈而过度的恐惧。','meaning'),[Q(1,'Why did she take the stairs even when the elevator was safe?','Her fear of elevators was unusually intense.','The elevator was broken and visibly dangerous.','She wanted to exercise before dinner.','A phobia is stronger than ordinary caution.'),Q(1,'Which reaction best suggests a phobia?','Avoiding a harmless elevator because of overwhelming fear.','Taking care around an elevator with a damaged door.','Choosing stairs once because the lobby is crowded.','A phobia is an intense fear disproportionate to ordinary risk.'),Q(1,'What does the Greek source phobos mean?','Fear.','Sound.','Wisdom.','Phobia derives from Greek phobos, “fear.”','word-formation'),Q(1,'Why is the example more than simple dislike?','The fear controls her behavior even when the elevator is safe.','She prefers one color over another.','She has never seen a lift.','The avoidance despite safety shows the intensity of the phobia.')]);
P('phoenix','Phoenix came through Latin phoenix from Greek phoinix, the name of the legendary bird said to renew itself from its ashes; the deeper origin of the name is uncertain.',C('phoenix.s1','文化','After the devastating fire, the town rebuilt its library and became a phoenix rising from the ashes.','大火重创后，小镇重建了图书馆，仿佛凤凰涅槃、浴火重生。','After the devastating fire / the town rebuilt its library / and became / a phoenix rising from the ashes.','phoenix.s1 指从自身灰烬中重生的传说之鸟，也可比喻毁后重建、重新兴起。','小镇灾后重建呼应凤凰重生的比喻。'),M('The phoenix died in the legend and never returned, so it became a symbol of permanent extinction rather than renewal.','The phoenix rose renewed from its ashes, making it a symbol of renewal after destruction.','凤凰传说的核心是焚毁后重生，不是永远灭绝。','meaning'),[Q(1,'Why was the rebuilt town compared with a phoenix?','It recovered and rose again after a destructive fire.','It moved permanently to another country.','It was an ordinary bird kept in a cage.','A phoenix is legendary for renewal from its ashes.'),Q(1,'What does a phoenix symbolize in the example?','Renewal after destruction.','A fear of elevators.','A phone conversation.','The town’s rebuilding echoes the phoenix’s return.'),Q(1,'Which detail belongs to the traditional phoenix legend?','The bird rises renewed from its ashes.','The bird is a small mammal that burrows.','The bird lives only underwater.','The mythical phoenix is associated with rebirth.'),Q(1,'Why should the name’s deeper origin be treated cautiously?','Its path into Greek and Latin is known, but the name’s deeper source is uncertain.','The word is definitely formed from phone + ix.','It comes from the Latin word for pharmacy.','The history of the name itself is uncertain.')]);
P('phone','Phone is a shortened form of telephone; telephone combines Greek tēle “far” and phōnē “sound, voice.”',[C('phone.s1','通信','The phone on the kitchen wall rang while Jae was checking the oven timer.','杰正在看烤箱计时器时，厨房墙上的电话响了。','The phone on the kitchen wall rang / while Jae was checking / the oven timer.','phone.s1 作名词，指远距离通话的装置或通信系统。','电话响铃提示有远程来电。'),C('phone.s2','通信','I will phone the clinic at noon to confirm whether the appointment is still available.','我会在中午给诊所打电话，确认预约时段是否还空着。','I will phone the clinic at noon / to confirm / whether the appointment / is still available.','phone.s2 作动词，指给某人或某机构打电话。','phone 后直接接通话对象 the clinic。','word-formation')],M('She phoned the clinic by sending a paper letter through the post instead of making a call.','She phoned the clinic by calling it on a telephone.','寄纸质信件不是打电话，不能称为 phoned。','meaning'),[Q(1,'What rang in the kitchen?','A telephone device on the wall.','A kitchen timer only.','A radio playing music.','Phone.s1 names a device used for distant conversation.'),Q(2,'What will the speaker do at noon?','Call the clinic to confirm the appointment.','Send the clinic a package of medicine.','Visit the clinic without contacting it.','Phone as a verb means telephone someone.'),Q(1,'What does the element tele- mean in telephone?','Far or at a distance.','Small or minor.','Write or record.','Telephone combines Greek tele “far” with phone “sound.”','word-formation'),Q(2,'Which sentence uses phone as a verb?','Please phone me when the train arrives.','My phone is charging on the desk.','The phone rang twice.','In the first sentence phone is an action directed at someone.','distinction')]);
P('phone call','Phone call is a compound of phone + call for a conversation made using a telephone.',C('phone call.s1','通信','The clinic returned Sam’s phone call and confirmed the appointment for Thursday morning.','诊所回了萨姆的电话，并确认预约在周四上午。','The clinic returned / Sam’s phone call / and confirmed / the appointment for Thursday morning.','phone call.s1 指通过电话进行的一次交谈或通话。','诊所回电并交流预约信息。','word-formation'),M('The clinic returned Sam’s phone call by sending him a silent photograph with no telephone conversation.','The clinic returned Sam’s phone call by telephoning him back to discuss the appointment.','phone call 指电话交谈，单发照片不是回电话。','meaning'),[Q(1,'How did the clinic respond to Sam?','It called him back and confirmed the appointment.','It mailed him a blank photograph.','It changed the appointment without contacting him.','A phone call is a conversation made by telephone.'),Q(1,'Which event is a phone call?','Two people speak to each other over a telephone.','Someone reads a letter silently.','A camera takes a picture of a phone.','The compound names a telephone conversation.'),Q(1,'What was discussed during the returned phone call?','The Thursday morning appointment.','The town’s rebuilt library.','The origin of the word phobia.','The call was used to confirm the appointment.'),Q(1,'Why is “returned the call” an apt description?','The clinic made a new telephone conversation in response to Sam’s earlier one.','The clinic returned a physical phone to a store.','The clinic mailed a petticoat back.','Returning a phone call means calling someone back.','distinction')]);
P('phone-in','Phone-in is a compound of phone + in from the verb phrase “phone in”; it names a broadcast that invites listeners or viewers to call the studio live.',C('phone-in.s1','媒体','The evening phone-in let listeners call the radio studio and ask the health expert questions on air.','晚间热线节目让听众打进广播室，现场向健康专家提问。','The evening phone-in let listeners / call the radio studio / and ask the health expert / questions on air.','phone-in.s1 指邀请观众或听众现场打电话参与的广播或电视节目。','打入直播间参与节目是 phone-in 的核心形式。','word-formation'),M('The station advertised a phone-in but prohibited every listener from calling the studio or joining the broadcast.','The station advertised a phone-in and invited listeners to call the studio during the broadcast.','phone-in 的定义包含观众现场来电参与，禁止所有来电与之相反。','meaning'),[Q(1,'How did listeners take part in the evening phone-in?','They called the studio and asked questions on air.','They mailed a letter after the show ended.','They watched a silent film in the studio.','A phone-in invites the audience to call in live.'),Q(1,'Which program is a phone-in?','A live radio show that takes callers’ questions.','A recorded lecture with no audience contact.','A printed newspaper column.','The defining feature is live phone participation.'),Q(1,'What does phone-in combine?','A telephone call-in with a broadcast program.','A photograph with a printed page.','A pharmacy with a laboratory.','The compound names a broadcast that takes incoming calls.' ,'word-formation'),Q(1,'Why were the questions “on air”?','The callers joined the live broadcast.','The expert sent answers by postal mail.','The callers were in a silent waiting room.','The phone-in aired participants’ calls live.')]);
P('phonemics','Phonemics is formed from phoneme + -ics; it analyzes the sound units that distinguish meaning in a particular language.',C('phonemics.s1','语言','In phonemics, the students tested whether replacing /p/ with /b/ changed the meaning of an English word.','在音位学练习中，学生检验把英语单词中的/p/换成/b/是否会改变词义。','In phonemics / the students tested / whether replacing /p/ with /b/ / changed the meaning of an English word.','phonemics.s1 指分析某种语言中能区别意义的音位及其格局。','替换一个音后词义变化，体现音位对比。','word-formation'),M('The phonemics lesson studied the color of speakers’ shirts instead of language sounds that distinguish words.','The phonemics lesson studied how sound contrasts distinguish words in the language.','phonemics 研究能区别词义的语音单位，不研究衣服颜色。','meaning'),[Q(1,'What did students test in the phonemics exercise?','Whether /p/ and /b/ distinguish word meanings.','Whether two shirts have the same color.','Whether a phone call was answered.','Phonemics studies distinctive sound units in a language.'),Q(1,'Which question belongs to phonemics?','Does changing one sound create a different word?','How does a medicine affect blood pressure?','How bright is a phosphorescent object?','The first question concerns meaning-distinguishing sound units.'),Q(1,'What does phonemics analyze?','The sound contrasts that function in a language.','The physical construction of a gramophone.','The history of ancient kings.','It analyzes distinctive phonological units.'),Q(1,'Why does replacing /p/ with /b/ matter in the example?','The sound change may create a different word.','It changes the speaker’s height.','It turns a noun into a petticoat.','A phonemic contrast can distinguish meanings.')]);
P('phonetic','Phonetic is from Greek phōnētikos, “vocal,” related to phōnē “sound”; it concerns speech sounds rather than spelling alone.',C('phonetic.s1','语言','The teacher wrote a phonetic transcription beside the unfamiliar name so students could pronounce it accurately.','老师在陌生姓名旁写下音标转写，帮助学生准确发音。','The teacher wrote / a phonetic transcription / beside the unfamiliar name / so students could pronounce it accurately.','phonetic.s1 指与言语声音有关的，而非只看拼写。','转写提示实际发音，不是照字母拼读。','word-formation'),M('The phonetic guide explained pronunciation by listing only silent spelling rules and giving no information about speech sounds.','The phonetic guide showed the speech sounds needed to pronounce the word.','phonetic 涉及语音；只列不发音的拼写规则并未说明语音。','meaning'),[Q(1,'Why did the teacher add a phonetic transcription?','To show how the unfamiliar name is pronounced.','To translate the name into another language.','To list the name’s owners.','Phonetic information represents speech sounds.'),Q(1,'Which guide is phonetic?','A guide that marks the sounds a speaker should produce.','A guide that gives only the word’s page number.','A guide that lists the price of a telephone.','The first guide concerns pronunciation and speech sounds.'),Q(1,'What does phonetic contrast with in the source definition?','Spelling considered by itself.','A live phone-in show.','A chemical element.','Phonetic refers to speech sounds, not just written letters.'),Q(1,'What can a phonetic spelling help a learner do?','Pronounce a name accurately.','Calculate a petroleum reserve.','Identify a bird rising from ashes.','A phonetic representation guides pronunciation.')]);
P('phonetics','Phonetics is the scientific study of the physical sounds of speech, from Greek phōnētikos “vocal” and phōnē “sound.”',C('phonetics.s1','语言','The phonetics lab used microphones and spectrograms to examine how speakers produce and perceive vowel sounds.','语音学实验室用麦克风和声谱图研究说话者如何发出并感知元音。','The phonetics lab used microphones and spectrograms / to examine how speakers produce / and perceive / vowel sounds.','phonetics.s1 指研究言语声音产生、传递和感知的科学。','设备记录语音并呈现其声学特征。','word-formation'),M('The phonetics course ignored speech sounds and focused entirely on the spelling of silent letters.','The phonetics course examined speech sounds and how people produce and hear them.','phonetics 研究实际言语声音，不是只研究沉默字母的拼写。','meaning'),[Q(1,'What did the phonetics lab examine?','How speakers produce and perceive vowel sounds.','How pharaohs signed royal decrees.','How pharmacies price prescriptions.','Phonetics studies the physical sounds of speech.'),Q(1,'Which tool could support phonetics research?','A spectrogram of recorded speech.','A petticoat pattern.','A map of oil reservoirs only.','A spectrogram can display the acoustic properties of speech sounds.'),Q(1,'What is the difference between phonetics and phonemics in this batch?','Phonetics studies physical speech sounds; phonemics studies sound units that distinguish meaning.','Phonetics studies medicines; phonemics studies their prices.','They both mean a live radio call-in.','The two fields focus on different aspects of sound.' ,'distinction'),Q(1,'What does phonetics study beyond pronunciation symbols?','The production, transmission, and perception of speech sounds.','The spelling of every word in a dictionary.','The history of a city’s name.','The science covers the physical sounds of speech.')]);
P('phonograph','Phonograph was coined from Greek phōnē “sound, voice” + graphein “write”; the noun names an early record player and the verb means record or play sound on one.',[C('phonograph.s1','科技史','The curator lowered the needle onto a wax cylinder, and the antique phonograph began playing a voice recorded more than a century ago.','馆长把唱针放到蜡筒上，古董留声机随即播放出一段百年前录制的声音。','The curator lowered the needle / onto a wax cylinder / and the antique phonograph / began playing a voice recorded more than a century ago.','phonograph.s1 指记录并重放声音的留声机，尤指早期机械式设备。','唱针和蜡筒体现早期留声机的结构。'),C('phonograph.s2','科技史','The museum staff phonographed the final interview onto a cylinder before the recording equipment was retired.','录音设备退役前，博物馆工作人员用留声机把最后一次采访录到蜡筒上。','The museum staff phonographed / the final interview / onto a cylinder / before the recording equipment was retired.','phonograph.s2 作动词，指用留声机录制或播放声音。','phonographed 在此表示用留声机录音。','word-formation')],M('The curator called a silent wax cylinder a phonograph even though it was the record player, not the sound carrier.','The curator called the machine that played the wax cylinder a phonograph.','phonograph 指播放或录制声音的机器；蜡筒是记录媒介。','distinction'),[Q(1,'What played the century-old voice in the museum?','An antique machine with a needle and wax cylinder.','A modern phone-in broadcast.','A silent paper photograph.','A phonograph is an early machine for recording or playing sound.'),Q(2,'What did the staff phonograph?','The final interview.','A picture of the cylinder.','A pharmacy prescription.','The verb means record or play sound on a phonograph.'),Q(1,'Which object is a phonograph?','A mechanical record player that reproduces recorded sound.','A microphone with no playback function.','A printed transcript of an interview.','The noun is a sound-recording and playback machine.'),Q(2,'In the second example, phonographed means what?','Recorded the interview using a phonograph.','Translated the interview into Greek.','Repaired the museum’s roof.','The verb names recording or playback on this machine.','distinction')]);
P('phosphate','Phosphate is recorded from 1795 through French phosphate, formed from phosphore “phosphorus” + the chemical suffix -ate, used for salts of acids ending in -ic.',C('phosphate.s1','化学','The soil test found a phosphate compound in the field, a nutrient that crops need for healthy root growth.','土壤检测在田地中发现了磷酸盐化合物，这种养分有助于作物根系健康生长。','The soil test found / a phosphate compound / in the field / a nutrient that crops need for healthy root growth.','phosphate.s1 指含磷酸根的化合物，常见于岩石、骨骼或肥料。','磷酸盐是作物所需的营养物质。','word-formation'),M('The lab identified the sample as a phosphate even though it contained no phosphorus compound or phosphate group.','The lab identified the sample as a phosphate because it contained a compound with a phosphate group.','phosphate 指含磷酸根的化合物，不含相关基团就不符合该名称。','meaning'),[Q(1,'What did the soil test find?','A phosphorus-containing compound useful to crops.','A telephone recorded on a wax cylinder.','A type of undergarment.','Phosphate is a compound containing the phosphate group.'),Q(1,'Where might a phosphate naturally occur?','In mineral rock or bone.','In a live radio phone-in only.','In a camera’s printed photograph only.','Phosphate compounds occur in rock and bone and are used by plants.'),Q(1,'What is the chemical role of -ate here?','It forms the name of a salt related to an acid ending in -ic.','It means a sound recorded on a disc.','It marks a person who gives to charity.','The suffix -ate forms names such as phosphate from phosphoric acid.' ,'word-formation'),Q(1,'Why is phosphate relevant to crop growth?','Plants need phosphate nutrients.','It is the name of a machine that plays records.','It is a chemical signal used by moths.','Phosphate compounds supply a nutrient plants use.')]);
P('phosphorescence','Phosphorescence was formed from French phosphorescence or English phosphoresce + -ence; it names light that continues after the energy source is removed.',C('phosphorescence.s1','物理','The glow paint showed phosphorescence, remaining visible for several minutes after the lamp was switched off.','灯光关闭几分钟后，夜光涂料仍然可见，表现出磷光现象。','The glow paint showed phosphorescence / remaining visible / for several minutes / after the lamp was switched off.','phosphorescence.s1 指激发能量撤去后仍持续一段时间的发光。','灯关后余辉仍持续，体现磷光与持续发光的特点。','word-formation'),M('The sign’s phosphorescence disappeared the instant the lamp was switched off and produced no afterglow at all.','The sign showed phosphorescence by continuing to glow after the lamp was switched off.','持续余辉才是 phosphorescence 的特征；瞬间消失没有余辉并非此现象。','meaning'),[Q(1,'What happened to the glow paint after the lamp was turned off?','It remained visible for several minutes.','It became a liquid phosphate.','It began ringing like a telephone.','Phosphorescence continues after the energy source is removed.'),Q(1,'Which material shows phosphorescence?','A surface that keeps glowing after the light is switched off.','A mirror that reflects light only while a lamp shines on it.','A paper copy made in an office.','The defining feature is continued emission after excitation stops.'),Q(1,'What does the noun phosphorescence name?','A persistent glow after an energy source is removed.','The act of printing a photograph.','A calm reaction to bad news.','The example describes persistent afterglow.'),Q(1,'How can the observer tell it is phosphorescence rather than ordinary reflection?','The glow continues after the lamp is off.','The surface is brightly colored in daylight.','The sign is mounted on a wall.','A continued glow after excitation distinguishes phosphorescence.','distinction')]);
P('phosphorus','Phosphorus comes from Latin phosphorus, “light-bringing,” from Greek Phosphoros “torchbearer,” formed from phōs “light” + phoros “bearer”; it later became the element’s name.',C('phosphorus.s1','化学','White phosphorus is stored under water because exposure to air can make it ignite easily.','白磷保存在水下，因为暴露于空气中可能使它容易燃烧。','White phosphorus is stored under water / because exposure to air / can make it ignite easily.','phosphorus.s1 指第15号化学元素磷；白磷是易燃的一种形态。','储存在水下是为了隔绝空气并降低白磷起火风险。','word-formation'),M('The technician left white phosphorus uncovered in open air because it cannot ignite or react.','The technician kept white phosphorus under water because it can ignite when exposed to air.','白磷遇空气可能燃烧，敞开放置并非安全做法。','meaning'),[Q(1,'Why was white phosphorus kept under water?','To limit its exposure to air because it can ignite easily.','To make it into a telephone wire.','To keep it glowing after every light is removed.','White phosphorus is highly reactive and can ignite in air.'),Q(1,'Which element is phosphorus?','The chemical element with atomic number 15.','A salt with no phosphorus atoms.','A sound-recording machine.','Phosphorus is element 15.'),Q(1,'What does the Greek name Phosphoros literally mean?','Torchbearer or light-bringer.','Lover of wisdom.','Little coat.','Phosphoros combines a word for light with one for bearer.' ,'word-formation'),Q(1,'Which form of phosphorus requires especially careful storage?','White phosphorus, which can ignite in air.','A photograph printed on paper.','A harmless cardboard model.','The example notes the combustible white form.')]);
P('photo','Photo is a shortened form of photograph; photograph was coined from Greek phōs “light” + graphein “write,” for an image made by recording light.',[C('photo.s1','摄影','Tariq took a photo of the harbor at dawn, catching the fishing boats as the sun rose behind them.','塔里克在黎明时拍了一张港口照片，拍下了太阳从渔船后升起的景象。','Tariq took a photo / of the harbor at dawn / catching the fishing boats / as the sun rose behind them.','photo.s1 指用相机拍摄的照片。','take a photo 是拍摄图像的常见搭配。'),C('photo.s2','摄影','The editor attached a digital photo of the damaged sign to the online report.','编辑把一张受损标牌的数码照片附在在线报告里。','The editor attached / a digital photo / of the damaged sign / to the online report.','photo.s2 指记录真实场景的纸质或数字图像。','文件附件中的图像记录了真实标牌。')],M('She attached a photo of the damaged sign, but the file was only a written recipe with no image.','She attached a photo of the damaged sign as a digital image showing its condition.','photo 指图像，不是没有图片的纯文字食谱。','meaning'),[Q(1,'What did Tariq take at dawn?','An image of the harbor and fishing boats.','A phone call with the harbor master.','A chemical sample from the water.','Photo.s1 is a picture taken with a camera.'),Q(2,'What did the editor attach to the report?','A digital image showing the damaged sign.','A spoken message with no image.','A petticoat pattern.','Photo.s2 includes a printed or digital image recording a real scene.'),Q(1,'What does the Greek element phōs mean in photograph?','Light.','Brother.','Oil.','Photograph was formed from Greek for light + write.' ,'word-formation'),Q(2,'Which item is a photo in the digital-file sense?','A saved image of a real street scene.','A paragraph describing the scene without an image.','A list of camera prices.','The second sense can be a digital image file.')]);
P('photocopy','Photocopy is formed from photo + copy; it names the act of reproducing a page on a photocopier and the resulting duplicate.',[C('photocopy.s1','办公','Please photocopy the signed consent form before filing the original in the clinic’s archive.','请先复印签字的同意书，再把原件存入诊所档案。','Please photocopy / the signed consent form / before filing the original / in the clinic’s archive.','photocopy.s1 作动词，指用复印机复制纸张内容。','句中 photocopy 直接接要复制的文件。'),C('photocopy.s2','办公','The clerk handed each witness a photocopy of the map so they could mark the route.','办事员给每位证人一份地图复印件，让他们标出路线。','The clerk handed each witness / a photocopy of the map / so they could mark / the route.','photocopy.s2 作名词，指复印机制作出的副本。','a photocopy 是一份可分发的副本。')],M('The clerk handed out a photocopy of the map, but every sheet was a unique hand-painted original.','The clerk handed out photocopies of the same map made by a copying machine.','photocopy 是复制件，不是每张都独立手绘的原作。','distinction'),[Q(1,'What did the office do before filing the original form?','It reproduced the signed form on a copier.','It destroyed the original.','It called the witnesses by phone.','Photocopy as a verb means reproduce a page on a photocopier.'),Q(2,'What did each witness receive?','A copied map.','The original signed consent form.','A recorded phone call.','A photocopy is the duplicate made by a copying machine.'),Q(1,'Which sentence uses photocopy as a verb?','Could you photocopy this receipt for my records?','I put the photocopy in the folder.','The photocopy was slightly crooked.','The first sentence shows the action of copying.'),Q(2,'Why could witnesses mark their routes on the photocopy?','They each had a duplicate of the map.','They were given the only original map one at a time.','The clerk described the route over the phone.','A photocopy provides a separate copy for each person.')]);
P('photodissociation','Photodissociation is formed from photo- “light” + dissociation; it names the decomposition of a molecule after absorbing energetic photons.',C('photodissociation.s1','化学','Ultraviolet light caused photodissociation of the molecule, splitting it into smaller fragments in the upper atmosphere.','紫外线引发了该分子的光解，使其在高层大气中裂解为更小的碎片。','Ultraviolet light caused / photodissociation of the molecule / splitting it into smaller fragments / in the upper atmosphere.','photodissociation.s1 指分子吸收足够能量的光子后发生分解。','紫外光提供能量，使分子键断裂。','word-formation'),M('The molecule underwent photodissociation in complete darkness without absorbing any light energy.','The molecule underwent photodissociation after absorbing energetic ultraviolet photons.','photodissociation 由吸收光能触发；全黑且未吸收光子与定义矛盾。','meaning'),[Q(1,'What caused the molecule to split in the example?','It absorbed ultraviolet photons.','It was photocopied many times.','It was cooled in darkness.','Photodissociation occurs when a molecule absorbs sufficiently energetic light.'),Q(1,'Which event is photodissociation?','Light energy breaks a molecule into smaller parts.','A camera records a city street.','A star emits visible light from its surface.','The compound names light-driven molecular decomposition.'),Q(1,'What does photo- contribute to photodissociation?','Light.','Sound.','A chemical salt.','Photo- refers to light in this compound.' ,'word-formation'),Q(1,'Why can ultraviolet light trigger the reaction?','Its photons can supply enough energy to break molecular bonds.','It is a paper duplicate of the molecule.','It has no interaction with matter.','The source definition requires photons of sufficient energy.')]);
P('photoelectric','Photoelectric combines photo- “light” with electric; it describes electrical effects produced by light.',C('photoelectric.s1','物理','A photoelectric sensor opened the automatic door when light falling on its detector generated an electrical signal.','光电传感器在照到探测器的光产生电信号后打开了自动门。','A photoelectric sensor opened / the automatic door / when light falling on its detector / generated an electrical signal.','photoelectric.s1 指与光引起的电效应有关的。','传感器把光照变化转成电信号。','word-formation'),M('The photoelectric sensor generated its signal in total darkness, with no light reaching the detector.','The photoelectric sensor generated an electrical signal when light reached its detector.','photoelectric 效应由光产生；没有光照时不能如此描述该触发。','meaning'),[Q(1,'What triggered the automatic door?','Light produced an electrical signal in the sensor.','A paper photograph touched the frame.','A caller spoke on a radio show.','Photoelectric describes electrical effects produced by light.'),Q(1,'Which device is photoelectric?','A detector that converts incoming light into an electrical response.','A mechanical bell with no light detector.','A petticoat made from reflective cloth.','The first device has an electrical effect caused by light.'),Q(1,'What does photo- mean in photoelectric?','Light.','Earth.','Sound.','The compound joins photo- with electric.' ,'word-formation'),Q(1,'Why did the sensor respond when light reached it?','Light caused an electrical signal.','A phone call changed its battery.','A chemical salt dissolved in water.','That is the photoelectric effect described by the adjective.')]);
P('photoflash','Photoflash combines photo + flash and names a brief burst of light used to illuminate a photograph.',C('photoflash.s1','摄影','The photographer used a photoflash to brighten the group portrait in the dim hall.','摄影师用闪光灯照亮了昏暗大厅里的集体照。','The photographer used / a photoflash / to brighten the group portrait / in the dim hall.','photoflash.s1 指拍照时用于照亮场景的短暂强光或闪光设备。','昏暗环境需要瞬间补光。','word-formation'),M('The photographer used a photoflash that stayed dark and produced no burst of light during the exposure.','The photographer used a photoflash that produced a brief burst of light during the exposure.','photoflash 的用途正是拍摄时发出瞬间强光。','meaning'),[Q(1,'Why did the photographer use a photoflash?','To illuminate the group in a dim hall.','To copy the portrait on paper.','To measure the hall’s floor plan.','A photoflash provides a short burst of light for a photograph.'),Q(1,'Which object is a photoflash?','A camera attachment that briefly lights a scene.','A lens cap that blocks all light.','A radio that takes listener calls.','The first device makes the brief flash used in photography.'),Q(1,'What does the compound photoflash combine?','Photography and a brief burst of light.','A chemical phosphate and a phone.','A musical phrase and a record.','Photo + flash names a camera light burst.' ,'word-formation'),Q(1,'When is a photoflash especially useful?','When the subject is in a dim setting.','When no photograph is being made and light must be avoided.','When measuring speech sounds.','Its function is to add light during a photograph.')]);
P('photogrammetry','Photogrammetry combines photo- with Greek-derived elements for drawing or recording and measurement; it measures shapes and positions from photographs.',C('photogrammetry.s1','测绘','Surveyors used photogrammetry on overlapping drone images to map the cliff’s height and the path of a landslide.','测绘员用无人机拍摄的重叠照片进行摄影测量，绘出悬崖高度和滑坡路径。','Surveyors used photogrammetry / on overlapping drone images / to map the cliff’s height / and the path of a landslide.','photogrammetry.s1 指根据照片测量现实中的尺寸和位置并制图。','重叠航拍图像用于测量地形。','word-formation'),M('The surveyors used photogrammetry by guessing the cliff’s dimensions without taking or analyzing any photographs.','The surveyors used photogrammetry by measuring the cliff from overlapping photographs.','photogrammetry 依赖照片测量；没有照片也未分析图像不属于该方法。','meaning'),[Q(1,'What did the surveyors map from drone images?','The cliff’s height and the landslide path.','The chemical formula of a phosphate.','The sound of an orchestra.','Photogrammetry extracts dimensions and positions from photographs.'),Q(1,'Which task is photogrammetry?','Calculating a building’s dimensions from overlapping images.','Copying a paragraph on a copier.','Recording speech on a wax cylinder.','Photogrammetry measures real objects using photographs.'),Q(1,'Why were overlapping images useful?','They provided views from which surveyors could infer shape and position.','They made the images impossible to compare.','They removed all information about distance.','Photogrammetric measurements use image views to map the scene.'),Q(1,'What does photogrammetry produce in the example?','A measured map of the terrain.','A new chemical element.','A live phone-in broadcast.','The method turns photograph measurements into maps.')]);
P('photograph','Photograph was coined from Greek phōs/phot- “light” + graphein “write or record”; it can name the image or the act of taking one.',[C('photograph.s1','摄影','The archivist found a photograph of the original bridge tucked inside a box of family letters.','档案员在一盒家庭信件中发现了一张老桥的照片。','The archivist found / a photograph of the original bridge / tucked inside / a box of family letters.','photograph.s1 作名词，指由相机拍摄并冲印或存储的图像。','旧桥图像本身是一张 photograph。'),C('photograph.s2','摄影','The reporter will photograph the damaged road before repair crews begin work.','维修队开工前，记者将为受损道路拍照。','The reporter will photograph / the damaged road / before repair crews / begin work.','photograph.s2 作动词，指用相机拍摄图像。','photograph 后接被拍摄对象 the damaged road。','word-formation')],M('The reporter photographed the road by describing it in a paragraph without using a camera.','The reporter photographed the road by taking its picture with a camera.','photograph 作动词指用相机拍摄，不是只用文字描述。','meaning'),[Q(1,'What did the archivist find among the letters?','An image of the original bridge.','A telephone from the bridge office.','A map made only from guesses.','Photograph.s1 is a picture taken and stored or printed.'),Q(2,'What will the reporter do before repairs start?','Take a camera picture of the damaged road.','Write only a paragraph about it.','Repair the road alone.','Photograph as a verb means take a picture with a camera.'),Q(1,'What does graphein mean in the word’s Greek formation?','To write or record.','To carry.','To fear.','Photograph joins light with writing or recording.' ,'word-formation'),Q(2,'Which sentence uses photograph as a verb?','They will photograph the new bridge at sunrise.','The photograph hangs in the archive.','A photograph was found in a box.','In the first sentence the word names the action of taking a picture.','distinction')]);
P('photographer','Photographer is formed from photograph + the agent suffix -er for a person who performs an activity.',C('photographer.s1','职业','The photographer waited beside the finish line to capture each runner as they crossed it.','摄影师在终点线旁等候，拍下每位跑者冲线的瞬间。','The photographer waited / beside the finish line / to capture each runner / as they crossed it.','photographer.s1 指以工作或爱好身份拍摄照片的人。','capture each runner 表明其工作是拍摄照片。','word-formation'),M('The photographer produced every image by writing captions and never took or handled a camera.','The photographer produced the images by taking pictures with a camera.','photographer 指拍摄照片的人，不是只写图片说明的人。','meaning'),[Q(1,'What was the photographer waiting to capture?','Runners crossing the finish line.','A chemical reaction in a lab.','A caller joining a radio show.','A photographer takes pictures of people or events.'),Q(1,'Who is a photographer?','A person who takes photographs as a job or hobby.','A person who only prints someone else’s captions.','A person who studies the moon’s phases.','The noun names someone who takes photographs.'),Q(1,'What does the suffix -er indicate in photographer?','A person who does the activity.','A location where the activity occurs.','A state that continues after light is removed.','-er forms an agent noun for a person who photographs.' ,'word-formation'),Q(1,'Which person fits the example?','Someone positioned to take pictures of runners.','Someone measuring speech sounds in a lab.','Someone selling petrol at a station.','The example describes a person taking event photographs.')]);
P('photographic','Photographic is formed from photograph + -ic; it can mean related to photography or so exact that it seems like a photograph.',[C('photographic.s1','摄影','The archive stored its photographic negatives in cool, dry sleeves to protect the images.','档案馆把摄影底片存放在阴凉干燥的保护袋中，以保护图像。','The archive stored / its photographic negatives / in cool dry sleeves / to protect the images.','photographic.s1 指与照片或摄影过程有关的。','photographic 修饰 negatives，指摄影底片。'),C('photographic.s2','描述','Her photographic memory let her recall the exact position of every object on the crowded desk.','她有照相般的记忆力，能回想起拥挤桌面上每件物品的确切位置。','Her photographic memory let her recall / the exact position / of every object / on the crowded desk.','photographic.s2 指细节准确逼真，仿佛照片一般。','逐件回忆确切位置体现如照片般精细的记忆。')],M('He had a photographic memory, so he could not remember any detail of the room after seeing it.','He had a photographic memory, so he could recall the room’s details with exceptional accuracy.','photographic memory 指极其准确、细节丰富的记忆，与完全记不住细节相反。','meaning'),[Q(1,'What did the archive protect in cool, dry sleeves?','Photographic negatives.','Phosphate fertilizer.','A set of phone-in questions.','Photographic.s1 relates to photographs and the process of taking them.'),Q(2,'What could her photographic memory recall?','The exact arrangement of objects on the desk.','Only the desk’s general color.','Nothing about the room.','The figurative sense means extraordinarily exact, like a photo.'),Q(1,'Which phrase uses photographic in the literal field-related sense?','Photographic equipment.','Photographic memory.','Photographic accuracy of recall.','The first phrase means equipment used for photography.'),Q(2,'What does “photographic memory” praise?','The ability to remember visual details accurately.','A camera that cannot store images.','A skill for developing petroleum.','The expression compares detailed memory with a photograph.','distinction')]);
P('photography','Photography combines photograph with -y to name the skill and activity of making pictures with a camera.',C('photography.s1','艺术','After years of landscape photography, Jo learned to use softer morning light to reveal texture in the hills.','多年从事风景摄影后，乔学会利用柔和的晨光表现山丘的纹理。','After years of landscape photography / Jo learned to use / softer morning light / to reveal texture in the hills.','photography.s1 指用相机成像的技艺和活动。','选择光线表现纹理体现摄影技巧。','word-formation'),M('Jo practiced photography by avoiding cameras and making every landscape image from memory alone.','Jo practiced photography by using a camera to make landscape pictures.','photography 是用相机成像的活动，完全不用相机画记忆图不符合。','meaning'),[Q(1,'What did Jo study through years of landscape photography?','How to make camera images of landscapes.','How to classify plant species.','How to tune a philharmonic orchestra.','Photography is the skill and activity of making pictures with a camera.'),Q(1,'Which activity is photography?','Using a camera to create images of a landscape.','Describing a landscape without taking a picture.','Measuring a cliff from old maps only.','The first action makes pictures with a camera.'),Q(1,'What did softer morning light help Jo reveal?','Texture in the hills.','The number of phone calls made overnight.','A molecule’s phosphate group.','Lighting choices are part of photographic technique.'),Q(1,'What does photography name here?','A camera-based visual art and activity.','A single electrical current.','A person who takes photographs.','Photography names the practice; photographer names the person.')]);
P('photojournalism','Photojournalism combines photo + journalism; it reports news through photographs as well as words.',C('photojournalism.s1','媒体','The photojournalism team documented the flood with images of rescue boats and families returning home.','图片新闻团队用救援船和居民返家的照片记录了洪灾。','The photojournalism team documented the flood / with images of rescue boats / and families / returning home.','photojournalism.s1 指用照片传递新闻故事的新闻报道方式。','照片本身承担记录和叙述新闻的作用。','word-formation'),M('The outlet called the report photojournalism even though it included no photographs and only printed a weather table.','The outlet called the report photojournalism because photographs carried part of the flood story.','photojournalism 要由照片承担报道内容；纯文字表格不符合。','meaning'),[Q(1,'How did the team document the flood?','With photographs of rescues and families returning.','With a chart containing no images or reporting.','With a live phone-in about orchestra music.','Photojournalism uses photographs to carry a news story.'),Q(1,'Which report is photojournalism?','A news story told in part through documentary photographs.','A list of weather numbers with no images.','A portrait unrelated to a current event.','The first combines news reporting with photographs.'),Q(1,'Why are the flood images more than decoration?','They show what happened and help carry the news story.','They replace every fact with an abstract symbol.','They only advertise a camera brand.','Photojournalism relies on photographs as reporting.'),Q(1,'What do the roots of photojournalism signal?','Photography used for journalism.','A study of musical phrasing.','A record player that writes sound.','The compound joins photo and journalism.','word-formation')]);
P('photosensitive','Photosensitive combines photo- “light” + sensitive; it describes something altered or harmed by light, or able to detect light.',C('photosensitive.s1','科技','The photosensitive paper darkened where sunlight reached it, so the technician kept the sheets in an opaque envelope.','阳光照到的地方使感光纸变暗，因此技术员把纸张保存在不透光的信封里。','The photosensitive paper darkened / where sunlight reached it / so the technician kept the sheets / in an opaque envelope.','photosensitive.s1 指会因光而变化或受损，或能够探测光的。','避光保存是因为材料会响应光线。','word-formation'),M('The photosensitive film was unaffected by bright sunlight and could detect no light at all.','The photosensitive film changed when exposed to bright sunlight.','photosensitive 表示会响应或受光影响；完全不受光影响与之相反。','meaning'),[Q(1,'Why did the technician store the paper in an opaque envelope?','Light changed the photosensitive paper.','The paper could not be folded.','The paper was a copy of a photograph.','Photosensitive materials respond to light.'),Q(1,'Which detector is photosensitive?','A sensor that reacts when light reaches it.','A switch that responds only to sound.','A sheet that cannot be affected by any light.','A photosensitive detector is able to detect light.'),Q(1,'What does photo- mean in photosensitive?','Light.','Sound.','Small.','The compound refers to sensitivity to light.' ,'word-formation'),Q(1,'Which storage choice fits the example?','Keep the light-sensitive sheets inside an opaque envelope.','Leave them in direct sun all day.','Store them under a transparent lamp.','Blocking light prevents unwanted exposure.')]);
P('photosphere','Photosphere was formed from photo- “light” + sphere; its astronomical sense names the luminous layer of the sun or another star from which visible light escapes.',C('photosphere.s1','天文学','A telescope’s filter allowed the observer to study granules on the Sun’s photosphere without looking directly at the bright disk.','望远镜滤镜让观测者能够研究太阳光球上的颗粒结构，而无需直视明亮日面。','A telescope’s filter allowed the observer / to study granules / on the Sun’s photosphere / without looking directly at the bright disk.','photosphere.s1 指恒星主要可见光逸出的发光层。','观测到的日面结构属于太阳发光表层。','word-formation'),M('The astronomer called the dark space far beyond a star its photosphere, although no visible light came from it.','The astronomer called the star’s visible-light-emitting layer its photosphere.','photosphere 是恒星主要可见光逸出的发光层，不是遥远且不发光的空间。','meaning'),[Q(1,'What did the observer study on the Sun?','Granules on its visible-light-emitting layer.','A phone call coming from the star.','The star’s chemical salts only.','The photosphere is the layer from which most visible light escapes.'),Q(1,'Which region is a star’s photosphere?','Its luminous outer layer visible to us.','A dark region far away with no emitted light.','A camera’s printed photograph.','The astronomical sense names the star’s luminous visible layer.'),Q(1,'What does photo- mean in photosphere?','Light.','Water.','Sound.','Photosphere combines the light element with sphere.' ,'word-formation'),Q(1,'Why did the observer use a filter?','To examine the bright solar photosphere safely.','To record a phone-in show.','To stop the star from producing any light.','A filter lets the observer study the Sun’s visible surface without looking directly at it.')]);
P('photosynthesis','Photosynthesis combines photo- “light” with synthesis; it names the process by which plants use light to make sugars from carbon dioxide and water.',C('photosynthesis.s1','生物','In photosynthesis, the bean seedlings used sunlight, water, and carbon dioxide to make sugars for growth.','在光合作用中，豆苗利用阳光、水和二氧化碳制造糖分以供生长。','In photosynthesis / the bean seedlings used sunlight, water, and carbon dioxide / to make sugars / for growth.','photosynthesis.s1 指植物利用光把二氧化碳和水转化为糖的过程。','阳光提供能量，糖是该过程生成的物质。','word-formation'),M('The seedlings carried out photosynthesis in darkness by making sugar without light, water, or carbon dioxide.','The seedlings carried out photosynthesis using light, water, and carbon dioxide to make sugars.','光合作用需要光，并利用水和二氧化碳制造糖。','meaning'),[Q(1,'What did the bean seedlings make during photosynthesis?','Sugars for growth.','Petrol for the greenhouse heater.','A photocopy of the leaves.','Photosynthesis turns light, water, and carbon dioxide into sugars.'),Q(1,'Which materials does the process use in the example?','Sunlight, water, and carbon dioxide.','Only oxygen and soil.','Only a photograph and a lamp.','These are the inputs named in the source sense.'),Q(1,'What does the photo- part of photosynthesis refer to?','Light.','A plant’s phylum.','A phone call.','Photosynthesis uses light to synthesize sugars.' ,'word-formation'),Q(1,'Why is the sentence about darkness incorrect?','It omits the light energy required for photosynthesis.','It says seedlings need a camera.','It mistakes sugar for a musical phrase.','The process depends on light as its energy source.')]);
P('phototropism','Phototropism is based on photo- “light” + tropism “turning”; it names an organism’s growth or movement toward or away from light.',C('phototropism.s1','生物','The seedlings showed phototropism: their stems curved toward the window where the strongest light entered.','幼苗表现出向光性：茎朝着光线最强的窗户弯曲。','The seedlings showed phototropism / their stems curved / toward the window / where the strongest light entered.','phototropism.s1 指生物随光刺激朝向或背离光线生长。','茎朝光源弯曲是向光生长。','word-formation'),M('The seedling showed phototropism by growing toward the darkest corner, away from the only light source.','The seedling showed positive phototropism by growing toward the light source.','例句描述向光性；朝着远离唯一光源的暗处生长与之相反。','meaning'),[Q(1,'What did the seedlings do in response to light?','Their stems curved toward the bright window.','Their roots became a phone line.','Their leaves copied the window on paper.','Phototropism is growth or movement in response to light.'),Q(1,'Which observation shows positive phototropism?','A shoot bends toward a lamp.','A shoot moves away from all light.','A leaf stays unchanged in darkness.','Positive phototropism is growth toward light.'),Q(1,'What does tropism contribute to phototropism?','A turning or movement in response to a stimulus.','A printed image.','A chemical group in phosphate.','Tropism ultimately comes from a Greek word for turning.' ,'word-formation'),Q(1,'Why did the stems curve toward the window?','They grew directionally in response to light.','The window chemically dissolved their cells.','The plant was making a phone call.','Directional growth toward a stimulus is phototropism.')]);
P('photovoltaic','Photovoltaic combines photo- “light” with voltaic, named after Alessandro Volta; it describes a device or effect that produces electricity from light.',C('photovoltaic.s1','能源','The photovoltaic panels on the school roof generated electricity from sunlight throughout the clear afternoon.','晴朗的午后，学校屋顶上的光伏板一直利用阳光发电。','The photovoltaic panels / on the school roof / generated electricity / from sunlight throughout the clear afternoon.','photovoltaic.s1 指把光转化为电能的。','阳光产生电力体现光伏效应。','word-formation'),M('The photovoltaic panel produced electricity from sunlight by blocking every ray of light from reaching its cells.','The photovoltaic panel produced electricity when sunlight reached its cells.','光伏板需要光照产生电力；完全遮住光线会阻断这个过程。','meaning'),[Q(1,'What did the school’s photovoltaic panels generate?','Electricity from sunlight.','A printed copy of the roof.','A phone signal from a radio studio.','Photovoltaic devices produce electricity from light.'),Q(1,'Which object is photovoltaic?','A solar cell that converts light into electric power.','A battery that stores no charge.','A phonograph that plays a record.','A photovoltaic cell converts light to electricity.'),Q(1,'What does photo- contribute to photovoltaic?','Light.','Sound.','A person who studies physics.','Photo- means light in the compound.' ,'word-formation'),Q(1,'Why did the panel stop producing much power under a cover?','The cover blocked the light needed to generate electricity.','The panel turned into a photosphere.','The panel was a photograph.','The photovoltaic effect depends on light reaching the cell.')]);
P('phrasal','Phrasal is formed from phrase + -al; it describes something formed as a phrase, especially a verb combined with an adverb or preposition.',C('phrasal.s1','语言','“Turn down” is a phrasal verb: the verb turn combines with down to mean refuse an offer.','“Turn down”是一个短语动词：动词 turn 与 down 结合，表示拒绝一项提议。','“Turn down” is / a phrasal verb / the verb turn combines with down / to mean refuse an offer.','phrasal.s1 指以短语构成的，尤指动词与副词或介词组合的。','turn 与 down 合在一起形成固定短语动词。','word-formation'),M('The teacher called “turn down” a phrasal verb even though it contained only a single word with no particle.','The teacher called “turn down” a phrasal verb because the verb combines with the particle down.','phrasal verb 包含动词和副词或介词小品词，不是单独一个词。','meaning'),[Q(1,'Why is “turn down” a phrasal verb?','The verb combines with down to form a meaning.','It is one noun with no second element.','It names a bright layer of a star.','A phrasal verb is a phrase built from a verb and an adverb or preposition.'),Q(1,'Which expression is phrasal?','Look after, meaning care for.','Photograph, meaning a camera image.','Pharynx, meaning part of the throat.','Look after combines a verb with a particle to form a phrase.'),Q(1,'What does the suffix -al do in phrasal?','Forms an adjective meaning related to a phrase.','Turns it into a person who speaks.','Means an intense fear.','Phrasal is the adjective built from phrase.' ,'word-formation'),Q(1,'In the example, what does “turn down” mean?','Refuse an offer.','Increase the volume.','Photograph a doorway.','The phrasal verb has the stated meaning “refuse.”')]);
P('phrase','Phrase came through French and Latin from Greek phrasis “speech, expression”; it can mean a word group, to word an idea, or a short musical unit.',[C('phrase.s1','语言','The phrase “under the weather” functions as a unit meaning that someone feels unwell.','短语“under the weather”作为一个意义单位，表示某人身体不舒服。','The phrase “under the weather” / functions as a unit / meaning that someone / feels unwell.','phrase.s1 指构成一个意义单位的一小组词。','多个词组合后表达固定含义。'),C('phrase.s2','写作','The editor asked Mara to phrase the warning more clearly so readers would understand the risk.','编辑请玛拉把警告措辞写得更清楚，让读者理解风险。','The editor asked Mara / to phrase the warning / more clearly / so readers would understand the risk.','phrase.s2 作动词，指用特定方式说出或写出想法。','phrase the warning 是选择表达方式。','word-formation'),C('phrase.s3','音乐','The violinist repeated the opening phrase softly before the orchestra entered.','管弦乐队进入前，小提琴手轻柔地重复了开头的乐句。','The violinist repeated / the opening phrase / softly / before the orchestra entered.','phrase.s3 指音乐中像句子一样的一小段旋律。','小提琴演奏的开头旋律是一个乐句。')],M('The editor phrased the warning clearly by leaving the sentence unfinished and hiding its main point.','The editor phrased the warning clearly by stating the risk in direct, complete words.','把句子写残缺、隐藏重点不是清楚地措辞。','meaning'),[Q(1,'What does “under the weather” mean as a phrase?','That someone feels unwell.','That someone is standing outdoors.','That the sky is clear.','A phrase can be a small group of words with a unit meaning.'),Q(2,'What did the editor ask Mara to do?','Express the warning in clearer words.','Play a violin melody.','Divide the sentence into syllables only.','To phrase an idea is to put it into chosen words.'),Q(3,'What did the violinist repeat?','A short opening musical unit.','A sentence about being ill.','A phone-in question.','Phrase can name a short musical unit similar to a sentence.'),Q(2,'Which sentence uses phrase as a verb?','She phrased the answer carefully.','The phrase contains three words.','The singer ended the phrase on a high note.','In the first sentence phrase describes how the answer was worded.','distinction')]);
P('phylum','Phylum is the modern biological classification term from Greek phylon “tribe, race”; it names a major group of organisms sharing a basic body plan.',C('phylum.s1','生物','Biologists placed the starfish in the phylum Echinodermata, whose members share a distinctive body plan.','生物学家把海星归入棘皮动物门，该门生物具有共同的基本体制。','Biologists placed the starfish / in the phylum Echinodermata / whose members share / a distinctive body plan.','phylum.s1 指共享基本体制的一大类生物，即生物分类中的“门”。','共同的身体结构特征用于归类。','word-formation'),M('The biologist assigned the starfish to a phylum consisting of unrelated objects with no shared body plan.','The biologist assigned the starfish to a phylum whose organisms share a basic body plan.','phylum 是有共同基本体制的生物大类，并非毫无关联的物体集合。','meaning'),[Q(1,'Why did the biologists place starfish in Echinodermata?','It is a major group whose members share a body plan.','It is a kind of phone call.','It is a chemical element.','A phylum groups organisms with a basic body plan.'),Q(1,'What does phylum mean in biological classification?','A major group of related organisms.','A single individual animal.','A group of unrelated objects.','A phylum is a broad taxonomic group.'),Q(1,'What is the plural of phylum?','Phyla.','Phylumses.','Philosophies.','Phylum has the Greek-derived plural phyla.' ,'word-formation'),Q(1,'Which feature helps define the group in the example?','Its members share a distinctive body plan.','Its members all live in one aquarium.','Its members were photographed by one person.','Shared body organization is the criterion given.')]);
P('physic','Physic comes through French fisike from Latin physica and Greek physikē, “knowledge of nature”; its older medical uses mean give medicine or a medicine, especially a purgative.',[C('physic.s1','历史医学','In the old diary, the village doctor would physic a patient with a bitter remedy when fever persisted.','在旧日记中，村医会在病人持续发烧时给他服用苦味药剂。','In the old diary / the village doctor would physic a patient / with a bitter remedy / when fever persisted.','physic.s1 作旧式动词，指给某人用药治疗，过去常指服用泻药。','医生给患者用药，体现旧式动词义。'),C('physic.s2','历史医学','The apothecary warned that the physic was a strong purge and should not be taken casually.','药剂师提醒说，这种药是强效泻剂，不应随意服用。','The apothecary warned / that the physic was a strong purge / and should not be taken / casually.','physic.s2 作旧式名词，指药物，尤指泻药。','strong purge 指具有通便作用的药剂。')],M('The physician physicked the patient by withholding all treatment and giving no medicine.','The physician physicked the patient by administering a medicinal remedy.','physic 作动词意为给药；不给任何治疗与之相反。','meaning'),[Q(1,'What did the village doctor do in the diary?','He gave the patient a medicinal remedy.','He photographed the fever.','He changed the moon’s phase.','Physic as an old verb means administer medicine.'),Q(2,'What was the apothecary’s physic?','A strong purgative medicine.','A phone-in program.','A star’s visible layer.','Physic as a noun can mean medicine, especially a purge.'),Q(1,'Which sentence uses physic as a verb?','The doctor would physic the patient with a remedy.','The physic was stored in a glass bottle.','The phrase formed a unit of meaning.','The first sentence uses physic for treating someone with medicine.'),Q(2,'Why did the apothecary advise caution?','The physic was a strong purge.','The medicine was a musical phrase.','The patient was a starfish.','Historically, physic could refer to a potent purgative.')]);
P('physical','Physical comes from Medieval Latin physicalis, from Latin physica “study of nature” and Greek physikos “of nature”; senses include bodily, tangible, physics-related, and a medical examination.',[C('physical.s1','健康','The physical strain of carrying heavy boxes all day left his shoulders sore.','整天搬重箱子带来的身体劳累使他的肩膀酸痛。','The physical strain / of carrying heavy boxes all day / left / his shoulders sore.','physical.s1 指与身体或体力有关的。','酸痛来自身体活动，而非心理压力。'),C('physical.s2','日常','Before signing the contract, the buyer inspected the physical building rather than relying only on its online listing.','签合同前，买家检查了实物建筑，而不只依赖网上房源信息。','Before signing the contract / the buyer inspected / the physical building / rather than relying only on its online listing.','physical.s2 指作为真实物质存在、能够触摸的。','亲自查看实体建筑与网上信息相对。'),C('physical.s3','科学','The class used physical laws to predict how a metal ball would fall through the air.','全班运用物理定律预测金属球会如何穿过空气下落。','The class used / physical laws / to predict how / a metal ball would fall through the air.','physical.s3 指与物理学有关的。','定律用于解释物体运动，属于物理学。'),C('physical.s4','健康','The new employee completed a physical before starting work at the fire station.','这名新员工在消防站上岗前完成了体检。','The new employee completed / a physical / before starting work / at the fire station.','physical.s4 作名词，指对身体所做的医学检查。','入职前评估身体状况属于体检。')],M('The applicant completed a physical by having the doctor inspect a digital building model instead of examining the applicant’s body.','The applicant completed a physical by undergoing a medical examination of the body.','physical 作名词指体检，不是建筑模型检查。','meaning'),[Q(1,'Why were his shoulders sore?','He had done strenuous bodily work.','He had studied a philosophical argument.','He had made a photocopy.','Physical.s1 relates to the body and physical effort.'),Q(2,'What did the buyer inspect in person?','The real building that could be physically touched.','Only a picture on the website.','A formula about light.','Physical.s2 means existing as real matter.'),Q(3,'What kind of laws did the class use?','Laws of physics.','Rules for a phone-in show.','Rules for a petticoat.','Physical.s3 refers to physics as a science.'),Q(4,'What did the employee complete before starting at the fire station?','A medical examination of the body.','A language history seminar.','A music phrase.','As a noun, a physical is a medical examination.')]);
P('physically','Physically is physical + -ly; it means in bodily or material terms, and “physically impossible” can mean impossible under real-world conditions.',[C('physically.s1','通用','The rescue worker was physically exhausted after carrying supplies up the mountain for six hours.','救援人员连续六小时把物资搬上山后，身体上已筋疲力尽。','The rescue worker was physically exhausted / after carrying supplies / up the mountain / for six hours.','physically.s1 指就身体而言，或按照物质世界的规律。','exhausted 描述身体状态。'),C('physically.s2','逻辑','It is physically impossible for a person to be in two distant rooms at the exact same moment.','一个人不可能在同一时刻身处相距甚远的两个房间，这在现实中根本做不到。','It is physically impossible / for a person to be in two distant rooms / at the exact same moment.','physically.s2 可加强 impossible，表示在现实世界中根本不可能成立。','空间限制使同时出现在两地不可能。','distinction')],M('The climber was physically tired only in theory, while his body felt completely rested after the six-hour ascent.','The climber was physically tired after the six-hour ascent, and his body needed rest.','physically tired 指身体实际疲惫；身体完全休息好与“疲惫”相反。','meaning'),[Q(1,'Why was the rescue worker physically exhausted?','She carried supplies uphill for six hours.','She read a short phrase once.','She listened to one phone call.','Physically can describe the body’s actual condition.'),Q(2,'What does physically impossible mean in the second example?','Impossible under the real conditions of the physical world.','Very difficult but easy with practice.','Unpopular with most people.','The adverb can strengthen impossible to mean cannot exist in reality.'),Q(1,'Which sentence uses physically in a bodily sense?','He was physically sore after the long hike.','A square circle is physically impossible.','The report is a photojournalism feature.','The first describes a bodily state.'),Q(2,'Why is being in two distant rooms simultaneously physically impossible?','A person cannot occupy two separate locations at once.','The rooms have identical photographs.','The person dislikes both rooms.','The claim violates real-world spatial conditions.' ,'distinction')]);
P('physician','Physician came through Old French fisicien from Latin and Greek terms for natural science and healing; it names a qualified doctor, often one practicing internal medicine rather than surgery.',[C('physician.s1','医学','The physician listened to Mara’s symptoms, examined her, and prescribed treatment for the infection.','医生听取玛拉的症状，给她做了检查，并为感染开了治疗方案。','The physician listened to Mara’s symptoms / examined her / and prescribed treatment / for the infection.','physician.s1 指有资质诊治疾病的医生，通常不实施手术。','问诊、检查和开药体现临床诊疗。'),C('physician.s2','医学','The hospital’s physician treated the patient’s pneumonia with medication, while a surgeon handled the unrelated fracture repair.','医院的内科医生用药治疗患者的肺炎，另一位外科医生则处理无关的骨折修复。','The hospital’s physician treated / the patient’s pneumonia with medication / while a surgeon handled / the unrelated fracture repair.','physician.s2 特指内科医生，与外科医生相对。','用药治疗肺炎与手术修复作出内外科对照。')],M('The physician treated the infection by performing an operation on a broken bone, with no diagnosis or medical care for the infection.','The physician treated the infection by diagnosing it and prescribing appropriate medicine.','没有诊断或治疗感染并非句中所说的 physician 诊疗行为。','meaning'),[Q(1,'What did the physician do for Mara?','Listened to symptoms, examined her, and prescribed treatment.','Repaired a bridge.','Photographed the infection.','A physician is a qualified doctor who treats illness.'),Q(2,'Which task did the hospital physician perform?','Treat the pneumonia with medication.','Operate on the unrelated fracture.','Tune the patient’s piano.','The example uses physician for an internal-medicine doctor.'),Q(1,'What distinguishes a physician from a surgeon in the second example?','The physician treats the illness with medicine rather than performing the operation.','The physician sells cameras.','The surgeon studies language history.','The sentence contrasts medical treatment and surgical repair.'),Q(2,'Which person would be called a physician here?','A doctor treating pneumonia with medication.','A technician repairing a camera.','A caller asking questions on live radio.','The second sense is an internal-medicine doctor.')]);
P('physicist','Physicist is formed from physics + -ist, the agent suffix for a person who specializes in a field.',C('physicist.s1','科学','The physicist measured how the metal ball accelerated down the track and compared the results with a force equation.','物理学家测量金属球沿轨道加速的情况，并把结果与力学方程进行比较。','The physicist measured / how the metal ball accelerated / down the track / and compared the results with a force equation.','physicist.s1 指专门研究物理学的专家。','研究运动并使用物理方程体现其专业领域。','word-formation'),M('The physicist specialized in the study of force and motion but was described as an expert in ancient music instead.','The physicist specialized in the study of force and motion.','研究力和运动属于物理学，不是古代音乐研究。','distinction'),[Q(1,'What did the physicist measure?','The ball’s acceleration down the track.','The color of a petticoat.','The size of a pharynx.','A physicist specializes in physics, including motion and force.'),Q(1,'Who is a physicist?','A scientist who studies matter, energy, and physical laws.','A person who plays piano professionally.','A doctor who treats children only.','A physicist is a specialist in physics.'),Q(1,'What does -ist indicate in physicist?','A person who practices or specializes in a field.','A process of decomposition by light.','A place to buy medicine.','The suffix forms a person noun from physics.' ,'word-formation'),Q(1,'Which topic would fit the example’s physicist?','How force affects a moving ball.','How words changed in medieval texts.','How a city got its Greek name.','The question about acceleration is within physics.')]);
P('physics','Physics comes from Greek ta physika, “the natural things,” through Latin physica; it is the science of matter, energy, force, and motion, and can refer to laws explaining a particular system.',[C('physics.s1','科学','In physics, the class tested how changing a ramp’s height affected the motion of a rolling cart.','在物理学课堂上，学生测试了改变斜坡高度如何影响滚动车的运动。','In physics / the class tested / how changing a ramp’s height / affected the motion of a rolling cart.','physics.s1 指研究物质、能量、力和运动的科学。','测量斜坡与运动之间关系是物理实验。'),C('physics.s2','科学','The physics of the instrument depends on how a taut string vibrates when a musician plucks it.','这种乐器的物理原理取决于乐手拨动绷紧的琴弦时，琴弦如何振动。','The physics of the instrument depends / on how a taut string vibrates / when a musician / plucks it.','physics.s2 指解释某一事物如何运作的物理规律。','琴弦振动解释乐器发声的原理。')],M('The physics of the rolling cart explained nothing about motion, force, or how its ramp affected its speed.','The physics of the rolling cart explained how force and ramp height affected its motion.','物理学研究运动与力；若完全不涉及这些规律，就不是对其物理原理的解释。','meaning'),[Q(1,'What relationship did the class test in physics?','How ramp height affected a cart’s motion.','How a word’s spelling changed.','How a moth followed a pheromone.','Physics studies matter, energy, force, and motion.'),Q(2,'What explains the instrument’s sound in the second example?','The vibration of its taut string.','The city’s public square.','A printed copy of a score.','The phrase “the physics of” can name laws explaining a particular system.'),Q(1,'What kinds of things does physics study?','Matter, energy, force, and motion.','Only literary texts and language history.','Only public squares in Italy.','These are central topics of physics.'),Q(2,'What does “the physics of the instrument” refer to?','The laws that explain how the instrument behaves.','The instrument’s purchase receipt.','The name of the musician.','The second sense points to the system’s physical principles.','distinction')]);
P('physiological','Physiological is formed from physiology + -ical; it means related either to how a living body works or to the scientific study of those functions.',[C('physiological.s1','医学','A physiological response to the heat included sweating and a faster pulse as the body tried to cool itself.','身体为降温而出汗、脉搏加快，这是一种对高温的生理反应。','A physiological response to the heat / included sweating / and a faster pulse / as the body tried to cool itself.','physiological.s1 指与活体身体的运作过程有关的。','出汗和脉搏变化是身体功能反应。'),C('physiological.s2','教育','The journal published a physiological study of how muscle cells use oxygen during exercise.','该期刊发表了一项关于运动时肌肉细胞如何利用氧气的生理学研究。','The journal published / a physiological study / of how muscle cells use oxygen / during exercise.','physiological.s2 指属于生理学这门学科的。','研究肌肉功能的论文属于生理学领域。')],M('Sweating in the heat is a physiological response, but it has no connection to how the body functions.','Sweating in the heat is a physiological response produced by the body.','生理反应本身就是身体功能的一部分。','meaning'),[Q(1,'What happened as the body tried to cool itself?','It produced sweat and a faster pulse.','It formed a pictogram.','It made the moon change phase.','These are physiological responses of a living body.'),Q(2,'What did the journal publish?','A study of how muscle cells use oxygen.','A photojournalism feature.','A phylum classification chart only.','A study of body function belongs to physiology.'),Q(1,'Which event is physiological?','A body raises its temperature-regulating response during heat.','A person chooses a phrase for a letter.','A camera copies a photograph.','The first event concerns a living body’s function.'),Q(2,'What does physiological mean in “a physiological study”?','Belonging to the science of body functions.','Relating to a film shown in a cinema.','Made by a photocopier.','The adjective can describe work within physiology.','distinction')]);
P('physiologically','Physiologically is formed from physiological + -ly; it means with respect to the processes and functions of a living body.',C('physiologically.s1','医学','Although the runners were equally tired, they responded physiologically in different ways: one cooled quickly while the other kept sweating.','尽管跑者同样疲惫，他们的生理反应各不相同：一人很快降温，另一人则持续出汗。','Although the runners were equally tired / they responded physiologically / in different ways / one cooled quickly while the other kept sweating.','physiologically.s1 指就身体功能和生理过程而言。','冷却和出汗是身体调节过程。'),M('The report compared the runners physiologically by discussing only their favorite music and ignoring every bodily process.','The report compared the runners physiologically by examining their cooling and sweating responses.','生理比较应关注身体过程，而不是只谈音乐喜好。','meaning'),[Q(1,'What did the report compare physiologically?','The runners’ cooling and sweating responses.','Their favorite musical phrases.','Their photographs of the race.','Physiologically concerns bodily processes.'),Q(1,'Which question is physiological in focus?','How does the body regulate heat during a run?','Which song did the runner enjoy most?','Which city hosted the race?','The first asks about a bodily function.'),Q(1,'What does the -ly ending do in physiologically?','Forms an adverb meaning “with respect to physiology.”','Names a person who studies pictures.','Means a public square.','The adverb is built from physiological.' ,'word-formation'),Q(1,'Why might two equally tired runners respond differently physiologically?','Their bodily regulation processes may differ.','They are both using a photocopier.','They are members of different orchestras.','The adverb directs attention to body-function differences.')]);
P('physiology','Physiology comes from Greek physiologia, the study of nature and living functions; it names both the scientific field and the way a body or organ works.',[C('physiology.s1','医学','She chose physiology because she wanted to study how the heart, lungs, and other organs function in a living body.','她选择了生理学，因为她想研究心脏、肺和其他器官如何在活体中运作。','She chose physiology / because she wanted to study / how the heart, lungs, and other organs / function in a living body.','physiology.s1 指研究生物体及器官功能的科学。','学习心肺等器官工作方式属于生理学。'),C('physiology.s2','医学','The patient’s unusual physiology made her body process the medication more slowly than expected.','这名患者特殊的生理机能使她的身体处理药物的速度比预期更慢。','The patient’s unusual physiology made her body / process the medication / more slowly / than expected.','physiology.s2 指身体或器官通常的运作方式。','药物代谢快慢取决于身体机能。','word-formation')],M('The patient’s physiology meant the way her body functioned, but the report used it to mean the color of her clothing.','The patient’s physiology meant the way her body functioned, including how it processed medication.','physiology 描述身体的功能方式，不是衣物颜色。','meaning'),[Q(1,'Why did she choose physiology?','She wanted to study how organs function.','She wanted to learn to play the piano.','She wanted to map a public square.','Physiology is the scientific study of living-body functions.'),Q(2,'Why did the medication act slowly for the patient?','Her body processed it differently because of her physiology.','Her clothing was a different color.','She studied a different phylum.','Physiology can name how a particular body works.'),Q(1,'Which topic belongs to physiology?','How the lungs exchange gases.','How to phrase a warning.','How an orchestra performs softly.','The first concerns the function of a living organ.'),Q(2,'What does “the patient’s physiology” refer to?','The way her body functions.','The science of musical composition.','A photograph of the patient.','The second sense names an individual body’s functioning.','distinction')]);
P('physique','Physique came through French physique from Greek-derived terms for the physical or natural body; it names a person’s build, shape, and strength.',C('physique.s1','健康','The swimmer’s broad shoulders and strong back gave her a powerful physique suited to long-distance races.','这位游泳运动员宽阔的肩膀和强壮的背部构成了适合长距离比赛的健实体格。','The swimmer’s broad shoulders and strong back / gave her / a powerful physique / suited to long-distance races.','physique.s1 指一个人的体格、体形和身体强健程度。','肩背形态和力量共同体现其体格。'),M('The coach described her physique as her body build and strength, then claimed the word meant her favorite poem.','The coach described her physique as her body build and strength.','physique 指体格或体形，不是喜爱的诗。','meaning'),[Q(1,'What features shaped the swimmer’s physique?','Her broad shoulders and strong back.','Her favorite poem and song.','The dimensions of a public square.','Physique names a person’s body shape and strength.'),Q(1,'Which description concerns physique?','A runner’s sturdy build and muscular legs.','A runner’s choice of music.','A runner’s camera settings.','The first describes body build and strength.'),Q(1,'What does physique not mean in the example?','A person’s favorite poem.','A person’s body shape.','A person’s physical build.','Physique concerns bodily form, not a literary preference.'),Q(1,'Why was the swimmer’s physique suited to long races?','Her strong build supported the demands of swimming.','She could photocopy the race map.','She lived in an Italian piazza.','The sentence links body strength with the athletic event.')]);
P('phytoremediation','Phytoremediation is a modern compound of phyto- “plant” + remediation; it describes using plants and associated microbes to clean or stabilize contaminated soil or water.',C('phytoremediation.s1','环境科学','The mining company planted reeds for phytoremediation, allowing the roots and nearby microbes to absorb or stabilize metals in the wetland soil.','矿业公司种植芦苇进行植物修复，让根系及周围微生物吸收或稳定湿地土壤中的金属。','The mining company planted reeds / for phytoremediation / allowing the roots and nearby microbes / to absorb or stabilize metals in the wetland soil.','phytoremediation.s1 指利用植物及相关微生物清除或稳定污染土壤、水体。','植物根系和微生物参与污染物处理。','word-formation'),M('The site used phytoremediation by removing every plant and relying only on painted warning signs to clean the contaminated soil.','The site used phytoremediation by growing plants that helped remove or stabilize contaminants.','植物修复依靠植物及相关微生物，警示牌不能净化土壤。','meaning'),[Q(1,'What did the mining company plant for phytoremediation?','Reeds whose roots and microbes could handle soil metals.','A row of warning signs.','A field of piano keys.','Phytoremediation uses plants and associated microbes to address contamination.'),Q(1,'Which project is phytoremediation?','Using wetland plants to stabilize pollutants in soil.','Using a photocopier to reproduce a map.','Using a pharynx to measure speech sounds.','The first project uses plants to clean or stabilize contamination.'),Q(1,'What does phyto- mean in phytoremediation?','Plant.','Light.','Wisdom.','The compound begins with the plant-forming element phyto-.' ,'word-formation'),Q(1,'Why can phytoremediation take time?','Plants and associated microbes need time to absorb or stabilize contaminants.','The word means to remove all plants.','The soil must be turned into a musical instrument.','The process works through living organisms and their interactions with pollutants.')]);
P('pianist','Pianist is formed from piano + -ist, naming someone who plays the piano, especially with skill.',C('pianist.s1','音乐','The pianist practiced the difficult passage slowly each morning before performing the concerto with the city orchestra.','这位钢琴家每天早晨慢练那段高难度乐章，然后与市交响乐团合作演奏协奏曲。','The pianist practiced / the difficult passage slowly / each morning / before performing the concerto with the city orchestra.','pianist.s1 指演奏钢琴的人，尤指有一定技艺者。','练习并演奏协奏曲体现钢琴演奏者的身份。','word-formation'),M('The pianist performed the concerto by playing only the flute and never touching a piano.','The pianist performed the concerto by playing the piano part.','pianist 指弹钢琴的人，只吹长笛不符合此职业身份。','meaning'),[Q(1,'What did the pianist practice each morning?','A difficult passage for a piano concerto.','A set of pharynx diagrams.','A phrase for a phone-in show.','A pianist plays the piano.'),Q(1,'Who is a pianist?','A skilled performer who plays the piano.','A person who measures landscapes from photos.','A person who treats patients with surgery only.','The suffix -ist identifies a person associated with an activity.'),Q(1,'What does -ist add to piano in pianist?','A person who plays the instrument.','A place for piano lessons.','A style of music played softly.','Pianist names the player.' ,'word-formation'),Q(1,'Why did the pianist rehearse slowly?','To master a difficult passage before the performance.','To measure the orchestra’s stage.','To treat a contaminated wetland.','The example ties piano practice to performance preparation.')]);
P('piano','Piano came from Italian pianoforte, literally “soft-loud,” referring to its ability to play at different volumes; it names the instrument and a soft-performance direction in music.',[C('piano.s1','音乐','A child pressed the piano’s keys and heard small hammers strike the strings inside the wooden case.','孩子按下钢琴琴键，听见琴箱内的小音槌敲击琴弦。','A child pressed / the piano’s keys / and heard small hammers / strike the strings inside the wooden case.','piano.s1 指有琴键、通过音槌敲击琴弦发声的大型乐器。','琴键带动音槌敲弦，说明发声机制。'),C('piano.s2','音乐','At the marked piano passage, the violinist softened her tone so the singer could be heard clearly.','到了标记为 piano 的乐段，小提琴手放轻了音量，好让歌手清晰可闻。','At the marked piano passage / the violinist softened her tone / so the singer / could be heard clearly.','piano.s2 作音乐术语，要求轻柔地演奏或演唱。','乐谱标记要求降低音量，而不是换乐器。','word-formation')],M('The score marked the passage piano, instructing the musicians to play it as loudly as possible.','The score marked the passage piano, instructing the musicians to play it softly.','音乐术语 piano 指轻柔演奏，与尽可能大声相反。','meaning'),[Q(1,'What happened when the child pressed the piano’s keys?','Hammers struck strings inside the instrument.','A phone connected to a radio studio.','The photo turned into a chemical salt.','A piano is a keyboard instrument that makes hammers strike strings.'),Q(2,'How did the violinist play the marked piano passage?','Softly.','As loudly as possible.','Without making any sound at all.','In music, piano is a direction to perform softly.'),Q(1,'What does the Italian source pianoforte mean literally?','Soft-loud.','Plant-remedy.','Light-writing.','The name refers to the instrument’s ability to play softly and loudly.' ,'word-formation'),Q(2,'Which use of piano is a music direction rather than an instrument?','The ensemble played the final phrase piano.','She practiced on the piano after school.','The piano has a row of keys.','The first sentence uses the notation meaning “softly.”','distinction')]);
P('piazza','Piazza came into English from Italian piazza, from Latin platea “courtyard, broad street,” ultimately from Greek plateia “broad street.”',C('piazza.s1','城市','Families gathered in the piazza at sunset while a street musician played beneath the arcades.','日落时，许多家庭聚集在广场上，街头音乐家在拱廊下演奏。','Families gathered / in the piazza / at sunset / while a street musician played beneath the arcades.','piazza.s1 指意大利城镇中的公共广场。','居民聚集和街头表演体现公共广场用途。','word-formation'),M('The residents met in the piazza, a private room inside one family’s locked apartment.','The residents met in the piazza, a public square in the center of town.','piazza 是公共广场，不是私人住宅房间。','meaning'),[Q(1,'Where did families gather at sunset?','In the town’s public square.','Inside a locked private apartment.','At a medical clinic.','A piazza is a public square in an Italian town.'),Q(1,'What might someone find in a piazza?','People meeting around an open town square.','A person’s private bedroom.','A star’s photosphere.','The word names an open public square.'),Q(1,'What does the source Latin platea mean?','A courtyard or broad street.','A phone call.','A short musical unit.','Piazza came through Latin platea for a courtyard or broad street.' ,'word-formation'),Q(1,'Why was a musician playing beneath the arcades?','The piazza is a shared public place where people gather.','The piazza is a sealed laboratory.','The piazza is a type of musical instrument.','The sentence places public activity in a town square.')]);
P('pick','Pick is recorded in early English with senses of pecking, digging with a pointed tool, plucking, and choosing; its early history likely blends Old English pician and Old Norse pikka, though the deeper root may be imitative.',[C('pick.s1','日常','At the bakery, Luis picked the loaf with the crispest crust from the display.','在面包店，路易斯从展示柜里挑了外壳最脆的一条面包。','At the bakery / Luis picked the loaf / with the crispest crust / from the display.','pick.s1 作动词，指从一组中挑选或决定要哪一个。','从多个面包中作出选择。'),C('pick.s2','园艺','We picked ripe tomatoes from the vines before the first frost arrived.','初霜到来之前，我们从藤上摘下成熟的番茄。','We picked ripe tomatoes / from the vines / before the first frost / arrived.','pick.s2 作动词，指从植株上采摘果实或花。','果实从藤上被摘下。'),C('pick.s3','日常','The blue route was the guide’s pick because it offered shade and an easier trail.','蓝色路线是导游选中的路线，因为它有树荫而且步道更轻松。','The blue route was / the guide’s pick / because it offered shade / and an easier trail.','pick.s3 作名词，指已选中的人或物，或最佳选择。','the guide’s pick 是导游选中的路线。'),C('pick.s4','工具','The climber used a pick to chip ice away from the narrow ledge.','攀登者用尖镐把狭窄岩架上的冰凿掉。','The climber used a pick / to chip ice away / from the narrow ledge.','pick.s4 作名词，指带尖金属头、用于凿硬地或冰的工具。','用尖头工具凿冰。')],M('Luis picked a loaf from the display by leaving every loaf untouched and refusing to choose one.','Luis picked a loaf from the display by selecting the one with the crisp crust.','pick 作选择义要求选中某个对象，拒绝挑选并未完成选择。','meaning'),[Q(1,'Which loaf did Luis choose?','The loaf with the crispest crust.','The loaf hidden in the kitchen.','No loaf at all.','Pick.s1 means choose one from a group.'),Q(2,'What did the group do to the tomatoes?','They removed ripe fruit from the vines.','They chose a shaded walking route.','They chipped ice from a ledge.','Pick.s2 means pluck fruit from a plant.'),Q(3,'What was the guide’s pick?','The blue route.','The loaf with the crisp crust.','The pointed ice tool.','As a noun, pick can name the chosen option.'),Q(4,'What did the climber use to chip ice?','A pointed metal tool.','A public square.','A printed photograph.','Pick.s4 names a pointed tool for breaking hard material.')]);
P('pick up','Pick up is a verbal phrase recorded from the early 14th century for lifting with the fingers; it later developed senses including collecting someone or something and learning casually.',[C('pick up.s1','日常','I can pick up the parcel from the post office after work and bring it to your apartment.','我下班后可以去邮局取包裹，再带到你公寓。','I can pick up the parcel / from the post office / after work / and bring it to your apartment.','pick up.s1 指去取、接某人或取回某物。','取包裹并带走体现收取义。'),C('pick up.s2','语言','During her summer job at the café, Hana picked up several useful phrases from regular customers.','暑期在咖啡馆工作时，哈娜从常客那里无意间学会了几句实用表达。','During her summer job at the café / Hana picked up / several useful phrases / from regular customers.','pick up.s2 指未经刻意学习而无意间听到或学会。','工作交谈中自然学会表达，体现非正式习得。','word-formation')],M('Hana picked up the phrases by studying them in a formal class for months, though the sentence says she learned them casually at work.','Hana picked up the phrases informally by hearing customers use them at work.','上下文明确是无意间学会，长期正式课程不符合 pick up 的该义。','meaning'),[Q(1,'What will the speaker pick up after work?','A parcel from the post office.','A new phrase from a customer.','A pickaxe from the mountain.','Pick up.s1 means collect or fetch an item.'),Q(2,'How did Hana learn the useful phrases?','She heard them naturally from regular customers.','She memorized them in a formal course for months.','She copied them from a photograph.','Pick up.s2 means learn or hear something without trying.'),Q(1,'Which sentence uses pick up to mean collect?','I will pick up my friend at the station.','I picked up a new accent by listening.','The team’s speed began to pick up.','The first is about collecting a person.'),Q(2,'Why is Hana’s learning described as casual?','She acquired phrases during ordinary conversations at work.','She took an examination in phonemics.','She collected a parcel from a post office.','The second sense is learning without deliberate study.','distinction')]);
P('pickaxe','Pickaxe combines pick + axe and names a heavy tool with a pointed end for breaking rock or hard ground.',C('pickaxe.s1','工具','The archaeologists used a pickaxe to loosen the hard limestone around the buried foundation.','考古学家用十字镐松动埋藏地基周围坚硬的石灰岩。','The archaeologists used a pickaxe / to loosen the hard limestone / around the buried foundation.','pickaxe.s1 指尖头重型破岩工具。','坚硬石灰岩需要尖头重工具破开。','word-formation'),M('The crew used a pickaxe to polish the delicate glass lens without risking a scratch.','The crew used a pickaxe to break the hard rock around the foundation.','pickaxe 是破岩重工具，不适合精细抛光玻璃镜片。','meaning'),[Q(1,'What did the archaeologists loosen with the pickaxe?','Hard limestone around the foundation.','A soft paper photograph.','The strings inside a piano.','A pickaxe is a heavy pointed tool for breaking rock.'),Q(1,'Which job calls for a pickaxe?','Breaking compact rock during excavation.','Copying a signed form.','Tuning a string instrument.','The tool is designed to break hard ground or rock.'),Q(1,'What does pickaxe combine?','Pick + axe.','Photo + sphere.','Philo + logy.','The compound names a pick-shaped axe tool.' ,'word-formation'),Q(1,'Why would a pickaxe be the wrong tool for a glass lens?','It is a heavy rock-breaking tool and could damage delicate glass.','It is designed to take photographs.','It makes the lens more photosensitive.','The example contrasts the tool’s heavy use with fragile glass.')]);
P('pickup','Pickup is a noun formed from pick up; it can name a light truck with an open bed or an act of collecting someone or something, and more broadly an improvement or gain.',[C('pickup.s1','交通','The contractor loaded bags of cement into the pickup’s open bed and drove to the building site.','承包商把几袋水泥装进皮卡的敞开货厢，开往工地。','The contractor loaded bags of cement / into the pickup’s open bed / and drove / to the building site.','pickup.s1 指驾驶室后有敞开货厢的小型轻卡。','敞开货厢装运水泥体现皮卡义。'),C('pickup.s2','日常','The afternoon pickup of the children took longer than usual because the school road was closed.','下午接孩子比平时花的时间更久，因为学校门前的道路封闭了。','The afternoon pickup of the children / took longer than usual / because the school road / was closed.','pickup.s2 指接人或取物的行为，也可指速度、健康或生意回升。','接孩子这个动作是 pickup 的名词义。')],M('The contractor loaded cement into the pickup’s open bed even though the vehicle had no cargo bed at all.','The contractor loaded cement into the pickup’s open cargo bed.','pickup truck 的关键特征是驾驶室后的敞开货厢。','meaning'),[Q(1,'What did the contractor load cement into?','A light truck with an open cargo bed.','A passenger piano.','A pharmacy cabinet.','Pickup.s1 names a light truck with an open bed.'),Q(2,'What took longer than usual?','Collecting the children from school.','Driving a cargo truck to the site.','A business recovery.','Pickup.s2 can mean the act of collecting people.'),Q(1,'Which item is a pickup in the vehicle sense?','A small truck with an open bed behind its cab.','A closed train carriage.','A music direction to play softly.','The defining vehicle feature is its open cargo bed.'),Q(2,'Which use means an act of collection?','The school pickup was delayed by traffic.','The pickup carried cement to the site.','Sales showed a pickup after the holiday.','The first refers to collecting children; sales pickup is a separate increase sense.')]);
P('picky','Picky is pick + -y; the adjective developed the sense of being overly selective or fussy, especially about small details.',C('picky.s1','性格','The picky eater inspected every ingredient label and refused the soup because it contained a trace of celery.','这个挑剔的食客检查每一张配料标签，因为汤里含有微量芹菜就拒绝喝。','The picky eater inspected / every ingredient label / and refused the soup / because it contained a trace of celery.','picky.s1 指对细节过分挑剔、难以取悦的。','仅因微量配料拒绝整份汤显示过度挑剔。','word-formation'),M('The picky diner happily ate every dish without checking ingredients or expressing any preferences.','The picky diner rejected the soup over a tiny ingredient detail.','picky 指对小细节过分挑选，毫无偏好地接受所有食物并不符合。','meaning'),[Q(1,'Why did the picky eater refuse the soup?','It contained a trace of celery.','It was served in a large bowl.','It was photographed before serving.','Picky describes someone who is fussy about small details.'),Q(1,'Which person is picky?','A guest who rejects a meal over one tiny ingredient.','A guest who gladly eats every dish offered.','A guest who helps serve the food.','The first person is unusually selective.'),Q(1,'What does the ending -y contribute to picky?','It forms an adjective describing a tendency or quality.','It turns the word into a public square.','It means an instrument for breaking rock.','Picky is formed from pick with the adjective-forming -y.' ,'word-formation'),Q(1,'What could a host expect from a picky guest?','Close scrutiny of ingredients and strong preferences.','No concern about the menu at all.','A spontaneous phone-in interview.','Picky guests are difficult to please.')]);
P('picnic','Picnic entered English from French piquenique; its deeper history is uncertain. The noun first described a shared meal or social gathering and later an outdoor meal; the verb means eat such a meal outdoors.',[C('picnic.s1','休闲','The family packed sandwiches and fruit for a picnic beside the lake on Sunday afternoon.','周日下午，一家人带上三明治和水果，在湖边野餐。','The family packed sandwiches and fruit / for a picnic / beside the lake / on Sunday afternoon.','picnic.s1 指通常为休闲而在户外吃的一顿饭。','食物被带到湖边户外享用。'),C('picnic.s2','休闲','If the weather stays dry, we will picnic in the park and walk along the river afterward.','如果天气保持干燥，我们就去公园野餐，之后沿河散步。','If the weather stays dry / we will picnic in the park / and walk along the river / afterward.','picnic.s2 作动词，指在户外吃野餐。','picnic 直接作动词说明户外用餐活动。','word-formation'),C('picnic.s3','口语','Getting all the permits before the deadline was no picnic, but the team finished the paperwork on time.','在截止日期前办齐所有许可证可不轻松，但团队还是按时完成了文书工作。','Getting all the permits before the deadline / was no picnic / but the team finished / the paperwork on time.','picnic.s3 常见于 no picnic，指一件事并不轻松或愉快。','no picnic 在此表示办手续十分费力。')],M('Getting the permits was no picnic, meaning the paperwork was extremely easy and pleasant.','Getting the permits was no picnic, meaning the paperwork was difficult and unpleasant.','no picnic 通常是否定比喻，表示不轻松或不愉快。','meaning'),[Q(1,'What did the family do beside the lake?','They ate an outdoor meal together.','They attended a laboratory class.','They repaired a pickup truck.','Picnic.s1 is an outdoor meal, usually for enjoyment.'),Q(2,'What will the group do if the weather stays dry?','Eat outdoors in the park.','Stay inside and photocopy a map.','Perform a piano passage softly.','Picnic as a verb means have an outdoor meal.'),Q(3,'What does “no picnic” mean about getting the permits?','It was difficult and not pleasant.','It was an easy outdoor meal.','It happened in a public square.','The phrase is figurative for a task that is not easy.'),Q(1,'Which sentence uses picnic as a verb?','They picnicked under the trees after the hike.','They packed a picnic for Sunday.','The hike was no picnic.','The first sentence uses the action “eat outdoors.”','distinction')]);
P('pictogram','Pictogram is formed from picto-, from Latin pictus “painted,” + -gram, “something written or marked”; it is a simple picture that stands for a word or idea.',C('pictogram.s1','视觉符号','A pictogram of a wheelchair on the station map showed which entrance was accessible.','车站地图上的轮椅象形图标明了哪个入口可以无障碍通行。','A pictogram of a wheelchair / on the station map / showed / which entrance was accessible.','pictogram.s1 指代表一个词或概念的简单图形符号。','轮椅图形直接代表无障碍入口。','word-formation'),M('The map used a pictogram for the accessible entrance, but the symbol was an unrelated paragraph with no image.','The map used a pictogram for the accessible entrance, shown by a simple wheelchair image.','pictogram 是用图形代表概念的符号，不是没有图像的整段文字。','meaning'),[Q(1,'What did the wheelchair pictogram identify?','The accessible station entrance.','The location of a piano.','The price of a phone call.','A pictogram is a simple image that stands for an idea.'),Q(1,'Which sign is a pictogram?','A simple image of a fork and spoon for a dining area.','A full paragraph describing the restaurant.','A blank square with no symbol.','The image represents the dining concept without relying on words.'),Q(1,'What does -gram contribute to pictogram?','Something drawn, written, or marked.','A person who performs music.','A stage in a process.','The suffix -gram is related to a mark or written/drawn item.' ,'word-formation'),Q(1,'Why can travelers understand the wheelchair pictogram quickly?','The image stands for the idea of accessible entry.','It spells out a long legal contract.','It measures the station’s floor area.','A pictogram communicates a concept through a simple picture.')]);
P('pictorial','Pictorial comes from Latin pictorius “of painting,” related to pictura “painting”; it can be a picture-focused publication or an adjective meaning using or relating to pictures.',[C('pictorial.s1','出版','The Sunday paper included a pictorial of the city’s old theaters, with photographs and short captions.','周日报纸刊登了一组关于这座城市老剧院的画报，配有照片和简短说明。','The Sunday paper included / a pictorial / of the city’s old theaters / with photographs and short captions.','pictorial.s1 作名词，指以图片为主要内容的刊物或版面。','大量照片和简短说明构成图画专题。'),C('pictorial.s2','艺术','The museum displayed a pictorial map that used drawings instead of labels alone to show the mountain trails.','博物馆展示了一幅图示地图，用绘图而非单靠文字标签来标出山间步道。','The museum displayed / a pictorial map / that used drawings / instead of labels alone / to show the mountain trails.','pictorial.s2 作形容词，指用图画表现或与图画有关的。','地图通过图示表现路线。','word-formation')],M('The pictorial map showed the trails pictorially using no images, symbols, or drawings at all.','The pictorial map showed the trails with drawings and visual symbols.','pictorial 表示以图画表达；完全没有图像符号的地图不符合。','meaning'),[Q(1,'What did the newspaper’s pictorial contain?','Photographs of old theaters with short captions.','A long text-only legal report.','A set of audio interviews with no images.','A pictorial is a publication or section mainly made up of pictures.'),Q(2,'How did the museum’s map show mountain trails?','It used drawings as well as labels.','It used no visual marks at all.','It played a recorded phone call.','Pictorial as an adjective means using or relating to pictures.'),Q(1,'Which item is a pictorial in the noun sense?','A magazine insert made mainly of photographs.','A single unlabeled trail marker.','A musical phrase played softly.','The first publication is picture-focused.'),Q(2,'What does pictorial mean in “pictorial map”?','The map uses visual images to represent information.','The map is made only of spoken directions.','The map is a small truck.','The adjective describes a map that communicates through pictures.','distinction')]);
P('picture','Picture comes from Latin pictura “painting,” from pictus, the past participle of pingere “to paint”; it can mean an image, a film, a situation, or forming an image in the mind.',[C('picture.s1','艺术','A picture of the old bridge hung above the desk, showing its stone arches in winter.','书桌上方挂着一幅老桥的图画，画中是冬日里的石拱。','A picture of the old bridge / hung above the desk / showing its stone arches / in winter.','picture.s1 指绘画、素描或照片等图像。','桥的图像作为墙上的画作展示。'),C('picture.s2','娱乐','The children watched a picture at the neighborhood cinema while their parents waited outside.','孩子们在社区电影院看电影，父母则在外面等候。','The children watched / a picture / at the neighborhood cinema / while their parents waited outside.','picture.s2 可指在电影院放映的影片。','在电影院观看的 picture 指电影。'),C('picture.s3','分析','The first sales report looked poor, but the full picture improved once the holiday figures were included.','第一份销售报告看起来不理想，但纳入节日数据后，整体情况有所好转。','The first sales report looked poor / but the full picture improved / once the holiday figures / were included.','picture.s3 比喻整体状况或局面。','full picture 指综合所有数据后的整体情况。'),C('picture.s4','想象','Try to picture the mountain village before the road was built, when travelers had to arrive by boat.','试着想象修路之前那个山村的样子，那时旅客必须乘船抵达。','Try to picture the mountain village / before the road was built / when travelers / had to arrive by boat.','picture.s4 作动词，指在头脑中想象或设想某物。','Try to picture 邀请读者形成心中画面。','word-formation')],M('The report said the full picture improved, but it used picture to mean a single framed photograph rather than the overall situation.','The report said the full picture improved, meaning the overall situation looked better after all the figures were included.','full picture 在该句中比喻整体局面，不是一张实体照片。','distinction'),[Q(1,'What hung above the desk?','An image showing the old bridge’s stone arches.','A film playing at the cinema.','A sales report.','Picture.s1 can mean a drawing, painting, or photograph.'),Q(2,'What did the children watch at the neighborhood cinema?','A film.','A framed painting at home.','A chart of sales figures.','Picture.s2 can mean a movie shown in a cinema.'),Q(3,'What improved when holiday figures were added?','The overall sales situation.','The physical frame above the desk.','The bridge’s stone arches.','The full picture means the complete situation.'),Q(4,'What does the instruction “picture the village” ask you to do?','Form an image of it in your mind.','Take a photograph of it immediately.','Build a road through it.','As a verb, picture means imagine or form a mental image.')]);

})();
